window.AUDIT = {"total": 527, "counts": {"confirmed": 499, "partly": 27, "not_found": 1}, "checked": "2026-10-29", "items": [{"app": "pipedrive", "field": "gotchas", "text": "\"App not found\" usually means the client ID/secret don't match or the app isn't available to that user.", "src": "https://docs.composio.dev/toolkits/pipedrive", "verdict": "partly", "quote": "Pipedrive usually shows \"App not found\" when the OAuth app used for the connection is not approved or available for that user/workspace.", "fix": "\"App not found\" usually means the OAuth app isn't approved or available for that user; also check that the client ID and secret belong to the same app.", "note": "Page gives 'not approved/available' as the usual cause; mismatched client ID/secret is only a troubleshooting check."}, {"app": "outlook", "field": "limits", "text": "Before verification: with risk-based step-up consent on, users in other tenants can't consent to multitenant apps registered after 8 Nov 2020 that ask for more than sign-in and profile.", "src": "https://learn.microsoft.com/en-us/entra/identity-platform/publisher-verification-overview", "verdict": "partly", "quote": "if risk-based step-up consent is enabled, users can't consent to most newly registered multitenant apps that aren't publisher verified.", "fix": "Before verification: with risk-based step-up consent on, users in other tenants can't consent to most unverified multitenant apps registered after 8 Nov 2020 that ask for more than sign-in and profile.", "note": "Page says 'most' such apps, not all."}, {"app": "outlook", "field": "gotchas", "text": "If an admin consents without prompt=consent, the consent only covers the admin's own account.", "src": "https://learn.microsoft.com/en-us/entra/identity-platform/howto-convert-app-to-be-multi-tenant", "verdict": "partly", "quote": "If an application requires admin consent and an admin signs in without the prompt=consent parameter being sent", "fix": "If the app needs admin consent and an admin consents without prompt=consent, the consent only covers the admin's own account.", "note": "Page limits this to apps that require admin consent; it continues: 'when the admin successfully consents to the application it applies only for their user account.'"}, {"app": "outlook", "field": "gotchas", "text": "Multitenant apps must call the /common or /organizations endpoint, not a tenant-specific one.", "src": "https://learn.microsoft.com/en-us/entra/identity-platform/howto-convert-app-to-be-multi-tenant", "verdict": "partly", "quote": "With a multitenant application, the application can't immediately tell which tenant the user is from, so requests can't be sent to a tenant's endpoint.", "fix": "Multitenant apps send sign-in requests to /common (or /organizations), but later token requests for an already signed-in user should go to that user's tenant endpoint.", "note": "Same page tells apps to use the tenant endpoint for subsequent token calls to avoid MSAL cache misses, so 'not a tenant-specific one' is overstated."}, {"app": "zoom", "field": "requirements", "text": "Publishing to external users requires domain validation for privacy, terms, redirect, webhook and home URLs.", "src": "https://developers.zoom.us/docs/build-flow/publish", "verdict": "partly", "quote": "We perform a one-time verification to make sure that the domain where you receive Zoom callbacks is owned by you.", "fix": "Publishing requires one-time domain validation for the privacy policy, OAuth redirect, chat subscription bot, webhook callback and home URLs.", "note": "Validated fields: Privacy Policy, OAuth redirect, Chat Subscription Bot, Webhook Callback and Home URLs. Page lists no terms-of-use URL (it lists a Chat Subscription Bot URL instead) and doesn't limit domain validation to external audiences."}, {"app": "zoom", "field": "requirements", "text": "Reviewers need test account credentials, and first submissions must use the Production client ID.", "src": "https://developers.zoom.us/docs/build-flow/publish", "verdict": "partly", "quote": "Make sure your environment is using the Production Client ID during authorization.", "fix": "Zoom asks for test credentials so reviewers can fully test the app, and first-time submissions must use the Production Client ID during authorization.", "note": "Page asks reviewers be given test credentials but frames them as 'Provide test account information (if any)', not a hard requirement."}, {"app": "zoom", "field": "requirements", "text": "Sharing a beta URL externally requires SSDLC docs, SAST and DAST results, and a privacy policy.", "src": "https://developers.zoom.us/docs/distribute/sharing-private-and-beta-apps", "verdict": "partly", "quote": "You must also submit any three of the following five artifacts:", "fix": "Sharing a beta URL externally requires SSDLC docs, SAST and DAST results, a privacy policy, any three of five extra security artifacts, and TLS 1.2 or higher.", "note": "Page also requires SSDLC docs, SAST/DAST results and a privacy policy; claim omits the required 3-of-5 security artifacts (pen test summary, security policy, etc.) and TLS 1.2+."}, {"app": "intercom", "field": "gotchas", "text": "The authorization URL must use the regional host (US, EU or AU) matching the customer's workspace.", "src": "https://developers.intercom.com/docs/build-an-integration/learn-more/authentication/setting-up-oauth", "verdict": "partly", "quote": "For the smoothest experience, redirect each customer to the host matching their workspace's region.", "fix": "Each region (US, EU, AU) has its own authorization host; matching it avoids an extra region-selection step and is required only when the customer signs in with Google.", "note": "Page says the US host still works for EU/AU customers via a region dropdown, except Google sign-in, so 'must' is overstated."}, {"app": "intercom", "field": "gotchas", "text": "You may be asked to cut scopes and resubmit, which restarts the review.", "src": "https://developers.intercom.com/docs/publish-to-the-app-store/review-publish-your-app", "verdict": "partly", "quote": "you may be asked to adjust your scopes and resubmit the app.", "fix": "You may be asked to adjust your scopes and resubmit the app for review.", "note": "Page doesn't say resubmitting restarts the review; it says the team 'will review it further'."}, {"app": "figma", "field": "limits", "text": "Before approval: a private app only works for users in the team or org it belongs to.", "src": "https://developers.figma.com/docs/rest-api/oauth-apps/", "verdict": "partly", "quote": "Private OAuth apps can be used to make requests on behalf of users in team or organization you associated your app with", "fix": "A private app only works for users in the team or org it belongs to, and it needs no Figma review.", "note": "Page says private apps don't require review by Figma, so 'Before approval' framing is wrong; the team/org restriction is permanent, not pre-approval."}, {"app": "salesforce", "field": "gotchas", "text": "Apps that skip pre-testing rarely pass review, and each resubmission adds 2-3 weeks.", "src": "https://developer.salesforce.com/docs/platform/isvforce/guide/security-review-how-it-works.html", "verdict": "partly", "quote": "Applicants who don’t test beforehand rarely pass and must resubmit after addressing security vulnerabilities identified during a review.", "fix": "Apps that skip pre-testing rarely pass review, and re-testing a resubmission typically takes 2-3 weeks (an estimate).", "note": "The 2-3 weeks is the typical time for Product Security to test a resubmission and is labeled an estimate; 'adds' overstates it."}, {"app": "airtable", "field": "limits", "text": "Keep token requests below 10 per second per token.", "src": "https://airtable.com/developers/web/api/oauth-reference", "verdict": "partly", "quote": "Note: frequent invalid refresh requests may result in token revocation. Please keep requests below 10 per second per token.", "fix": "Keep refresh requests below 10 per second per token.", "note": "The limit appears in a note about refresh requests, not token requests in general."}, {"app": "youtube", "field": "gotchas", "text": "Composio says its managed YouTube app's quota is shared across users and recommends your own app for production.", "src": "https://docs.composio.dev/toolkits/youtube", "verdict": "partly", "quote": "If you use the managed/default OAuth app, that quota can be shared across users, so production workloads can hit provider quota limits faster than expected.", "fix": "Composio says its managed YouTube app's quota can be shared across users and recommends creating your own Google Cloud OAuth app for production.", "note": "Read via the page's .md version (FAQ is collapsed in HTML). Page hedges 'can be shared', claim says 'is shared'."}, {"app": "quickbooks", "field": "gotchas", "text": "Development and production keys are separate, and sandbox redirect URIs can use localhost.", "src": "https://developer.intuit.com/app/developer/qbo/docs/develop/authentication-and-authorization/set-redirect-uri", "verdict": "partly", "quote": "Each app has two URIs: one for testing environments (i.e., sandboxes), and another for live, in-production apps.", "fix": "Sandbox and production redirect URIs are set separately, and sandbox redirect URIs can use localhost without HTTPS.", "note": "Page confirms localhost for sandbox ('You can add localhost (no HTTPS) as a URI for sandbox environments') but is about redirect URIs; it does not say development and production keys are separate."}, {"app": "twitter", "field": "gotchas", "text": "Access tokens last two hours, and refresh tokens are only issued with the offline.access scope.", "src": "https://github.com/xdevplatform/docs/blob/main/fundamentals/authentication/oauth-2-0/authorization-code.mdx", "verdict": "partly", "quote": "By default, the access token you create through the Authorization Code Flow with PKCE will only stay valid for two hours unless you’ve used the `offline.access` scope.", "fix": "By default, access tokens are valid for two hours unless the offline.access scope is used, and refresh tokens are only issued with the offline.access scope.", "note": "Refresh-token half confirmed ('If this scope is not passed, we will not generate a refresh token'). Claim drops the page's 'by default ... unless offline.access' qualifier on the two-hour lifetime."}, {"app": "googledrive", "field": "review", "text": "Google restricted scope verification plus a CASA security assessment (drive.file alone needs no scope review) | wait: Several weeks (Google's FAQ estimates 6 weeks)", "src": "https://developers.google.com/identity/protocols/oauth2/production-readiness/restricted-scope-verification", "verdict": "partly", "quote": "the restricted scopes verification process can potentially take several weeks to complete.", "fix": "Google restricted scope verification, plus a CASA security assessment if the app stores or transmits restricted-scope data on servers | wait: can take several weeks", "note": "Page makes the CASA assessment conditional on server access/transmission; it does not mention drive.file or the FAQ's 6-week estimate (6 weeks is on the FAQ page; drive.file non-sensitive is on the Drive scopes page)."}, {"app": "github", "field": "gotchas", "text": "GitHub App user tokens also expire after 8 hours by default; installation tokens expire after 1 hour.", "src": "https://docs.github.com/en/apps/oauth-apps/building-oauth-apps/differences-between-github-apps-and-oauth-apps", "verdict": "partly", "quote": "Installation access tokens expire after a predefined amount of time (currently 1 hour).", "fix": "GitHub App installation tokens expire after 1 hour, and GitHub App user access tokens can expire and be renewed with a refresh token.", "note": "The page gives the 8-hour figure only for OAuth app user tokens; it does not state an 8-hour default for GitHub App user tokens."}, {"app": "microsoftteams", "field": "gotchas", "text": "Multitenant apps must call the /common or /organizations endpoint, not a tenant-specific one.", "src": "https://learn.microsoft.com/en-us/entra/identity-platform/howto-convert-app-to-be-multi-tenant", "verdict": "partly", "quote": "requests are sent to a common endpoint (https://login.microsoftonline.com/common) that serves across all Microsoft Entra tenants", "fix": "Multitenant apps send sign-in requests to /common (or /organizations if they don't support personal accounts), but later token calls for an already signed-in user should go to that user's tenant endpoint.", "note": "Page explicitly says subsequent calls for a signed-in user should use the tenant's endpoint, so \"not a tenant-specific one\" is overstated."}, {"app": "monday", "field": "requirements", "text": "Marketplace apps are reviewed on product, engineering, security, privacy, support, docs and legal.", "src": "https://developer.monday.com/apps/docs/submit-your-app", "verdict": "partly", "quote": "assessing the product, engineering, security, privacy, content, assets, support, documentation, and legal aspects.", "fix": "Marketplace apps are reviewed on product, engineering, security, privacy, content, assets, support, documentation and legal.", "note": "Claim omits content and assets from the review areas."}, {"app": "box", "field": "gotchas", "text": "Box disables all unpublished platform apps when that enterprise setting is on.", "src": "https://support.box.com/hc/en-us/articles/49348283011731-Enterprise-Settings-Platform-Apps", "verdict": "partly", "quote": "When you select Disable unpublished platform apps by default, Box disables all unpublished platform apps by default.", "fix": "With Disable unpublished platform apps by default on, Box disables unpublished platform apps whose status an admin never manually changed; admins can re-enable them in Platform Apps.", "note": "Same page says the setting \"only affects apps whose status has not been manually changed by an admin\", so \"all\" is overstated."}, {"app": "asana", "field": "gotchas", "text": "Access tokens last one hour; refresh tokens are long-lived until the user revokes access.", "src": "https://developers.asana.com/docs/oauth", "verdict": "partly", "quote": "expires_in The number of seconds that the token is valid, typically 3600 (one hour) ... refresh_token If exchanging a code , this is a long-lived token", "fix": "Access tokens typically last one hour (3600 seconds); refresh tokens are long-lived and are used to get new access tokens when old ones expire.", "note": "Page doesn't say refresh tokens last until the user revokes access; it only calls them long-lived and documents a revoke endpoint."}, {"app": "discord", "field": "gotchas", "text": "Since June 10, 2026, App Verification and Privileged Intent review are separate processes.", "src": "https://docs.discord.com/developers/gateway/getting-started-with-privileged-intent-review", "verdict": "not_found", "quote": "", "fix": "As of June 10, 2026, the privileged intent review threshold is based on more than 10,000 unique users instead of 100+ servers, and approved apps must reapply annually.", "note": "Page lists the June 10, 2026 changes but never mentions App Verification or says the two processes are separate."}, {"app": "googlecalendar", "field": "limits", "text": "Before approval: unverified apps are capped at 100 new users for the lifetime of the project, and the cap cannot be reset.", "src": "https://support.google.com/cloud/answer/13463817", "verdict": "partly", "quote": "unverified apps that are accessing restricted or sensitive scopes have a 100 new-user cap restriction.", "fix": "Before approval: unverified apps that request sensitive or restricted scopes are capped at 100 new users for the lifetime of the project, and the cap cannot be reset.", "note": "Cap applies only to unverified apps accessing sensitive/restricted scopes; claim drops that qualifier. Lifetime/no-reset is stated: \"the user cap applies over the entire lifetime of the project, and it cannot be reset or changed.\""}, {"app": "googlecalendar", "field": "review", "text": "Google OAuth sensitive scope verification (includes brand verification) | wait: 3-5 business days (Google's FAQ estimates 10)", "src": "https://developers.google.com/identity/protocols/oauth2/production-readiness/sensitive-scope-verification", "verdict": "partly", "quote": "Note that your app might be eligible to complete brand verification as a subset of your sensitive scope verification request.", "fix": "Google OAuth sensitive scope verification (branding must be published first) | wait: typically 3-5 business days", "note": "Page says verification \"typically takes 3-5 business days\"; brand verification \"might\" be a subset and that published branding is required before requesting data access verification; the FAQ 10-day estimate is not on this page."}, {"app": "shopify", "field": "limits", "text": "Before approval: protected customer data needs no review only while the app is installed solely on development stores.", "src": "https://shopify.dev/docs/apps/launch/protected-customer-data", "verdict": "partly", "quote": "You don't need to submit a request for review for apps that are installed only on development stores.", "fix": "Before approval: a public app can use protected customer data without review only while installed solely on development stores; custom apps get level 1 and 2 access without review.", "note": "Page table shows protected customer data is \"Always available\" (no review) for custom apps, so \"only\" while on dev stores is overstated."}, {"app": "shopify", "field": "requirements", "text": "Public apps must request protected customer data access, and level 1 and 2 access requires review.", "src": "https://shopify.dev/docs/apps/launch/protected-customer-data", "verdict": "partly", "quote": "Level Public app Custom app Admin created custom app 1 Requires review Always available Always available 2 Requires review Always available Varies by plan", "fix": "Public apps that use protected customer data must request access, and level 1 and 2 access requires review.", "note": "Level 0 (no customer data) requires no action, so not every public app must request access."}, {"app": "shopify", "field": "review", "text": "Shopify App Store review (public distribution), plus protected customer data review if you read customer data | wait: not stated", "src": "https://shopify.dev/docs/apps/launch/distribution", "verdict": "partly", "quote": "Public distribution also requires registering for the Shopify App Store, which has a one-time fee.", "fix": "Public distribution requires Shopify approval and Shopify App Store registration | wait: not stated", "note": "Distribution page confirms approval is required for public distribution and gives no wait time, but does not mention a protected customer data review (that is on the protected-customer-data page)."}, {"app": "linkedin", "field": "gotchas", "text": "Composio's organization tools need w_organization_social or rw_organization_admin, which are not open permissions.", "src": "https://docs.composio.dev/toolkits/linkedin", "verdict": "partly", "quote": "w_organization_social scope for posting as an organization (with ADMINISTRATOR, DIRECT_SPONSORED_CONTENT_POSTER, or CONTENT_ADMIN role)", "fix": "Composio's LinkedIn organization tools need w_organization_social to post as an organization, rw_organization_admin for page and share statistics, and r_organization_admin for company info.", "note": "Quote is from tool metadata embedded in the page HTML (shown when a tool is expanded). Per that metadata, GET_COMPANY_INFO needs r_organization_admin (not in the claim); the Composio page does not say these are not open permissions (that comes from LinkedIn's getting-access page)."}], "confirmedSample": [{"app": "googlesheets", "field": "limits", "text": "Before approval: Testing mode is limited to 100 test users listed on the consent screen.", "src": "https://support.google.com/cloud/answer/15549945", "quote": "Projects configured with a publishing status of Testing are limited to up to 100 test users listed in the OAuth consent screen."}, {"app": "googlesheets", "field": "limits", "text": "Before approval: test-user authorizations and refresh tokens expire 7 days after consent.", "src": "https://support.google.com/cloud/answer/15549945", "quote": "Authorizations by a test user will expire seven days from the time of consent. If your OAuth client requests an offline access type and receives a refresh token, that token will also expire."}, {"app": "googlesheets", "field": "limits", "text": "Before approval: an In-production app requesting unapproved sensitive or restricted scopes shows the unverified app screen.", "src": "https://support.google.com/cloud/answer/15549945", "quote": "Google will display an Unverified apps warning message if your project's OAuth clients request authorization of scopes considered sensitive or restricted before your project has completed verification"}, {"app": "googlesheets", "field": "limits", "text": "Before approval: unverified apps are capped at 100 new users for the lifetime of the project, and the cap cannot be reset.", "src": "https://support.google.com/cloud/answer/13463817", "quote": "the user cap applies over the entire lifetime of the project, and it cannot be reset or changed."}, {"app": "googlesheets", "field": "requirements", "text": "Verify ownership of your authorized domains in Google Search Console.", "src": "https://developers.google.com/identity/protocols/oauth2/production-readiness/sensitive-scope-verification", "quote": "Verify ownership of your project's authorized domains within the Google Search Console."}, {"app": "googlesheets", "field": "requirements", "text": "Host a public home page and a privacy policy on the same domain, both linked from the consent screen.", "src": "https://developers.google.com/identity/protocols/oauth2/production-readiness/sensitive-scope-verification", "quote": "The privacy policy must be visible to users, hosted within the same domain as your application's home page, and linked to on the OAuth consent screen of the Google API Console."}, {"app": "googlesheets", "field": "requirements", "text": "The privacy policy must disclose how the app accesses, uses, stores, or shares Google user data.", "src": "https://developers.google.com/identity/protocols/oauth2/production-readiness/sensitive-scope-verification", "quote": "The privacy policy must disclose the manner in which your application accesses, uses, stores, or shares Google user data."}, {"app": "googlesheets", "field": "requirements", "text": "Give a written justification for each sensitive scope, including why a narrower scope is not enough.", "src": "https://developers.google.com/identity/protocols/oauth2/production-readiness/sensitive-scope-verification", "quote": "Prepare a detailed justification for each requested sensitive scope, as well as an explanation for why a narrower scope isn't sufficient."}, {"app": "googlesheets", "field": "requirements", "text": "Submit an unlisted YouTube video showing the consent flow, the client ID in the address bar, and each scope in use.", "src": "https://developers.google.com/identity/protocols/oauth2/production-readiness/sensitive-scope-verification", "quote": "Upload the video to YouTube Studio and set its Visibility as Unlisted."}, {"app": "googlesheets", "field": "requirements", "text": "You must publish your branding before you can request verification for data access.", "src": "https://developers.google.com/identity/protocols/oauth2/production-readiness/sensitive-scope-verification", "quote": "Note that you must have a published branding status before you can request verification for data access."}, {"app": "googlesheets", "field": "requirements", "text": "Internal-only apps (Workspace-owned project, Internal audience) skip verification and the 100-user cap but only work in that org.", "src": "https://support.google.com/cloud/answer/13464323", "quote": "Your app will not be subject to the unverified app screen or the 100-user cap if it's designated as internal-only."}, {"app": "googlesheets", "field": "gotchas", "text": "spreadsheets and spreadsheets.readonly are sensitive; drive.file is the recommended non-sensitive scope.", "src": "https://developers.google.com/workspace/sheets/api/scopes", "quote": "https://www.googleapis.com/auth/drive.file See, edit, create, and delete only the specific Google Drive files you use with this app. Recommended Non-sensitive"}, {"app": "googlesheets", "field": "gotchas", "text": "drive and drive.readonly also work with Sheets but are restricted, which adds a security assessment if you store or transmit the data on servers.", "src": "https://developers.google.com/workspace/sheets/api/scopes", "quote": "If you store restricted scope data on servers (or transmit), then you must go through a security assessment."}, {"app": "googlesheets", "field": "gotchas", "text": "Composio says its default OAuth app shares Sheets quota across users; your own app gets a dedicated quota.", "src": "https://docs.composio.dev/toolkits/googlesheets", "quote": "If you're using Composio's default OAuth app, you share that quota with other users, which can cause limits to be hit faster. Use your own OAuth app credentials to get a dedicated quota"}, {"app": "googlesheets", "field": "gotchas", "text": "Google's FAQ estimates sensitive scope verification at 10 business days, which is longer than the 3-5 days on the developer page.", "src": "https://support.google.com/cloud/answer/13463817", "quote": "Sensitive Scope Verification"}, {"app": "googlesheets", "field": "gotchas", "text": "Limits apply to refresh tokens: 100 per Google Account per client ID, and creating a new one silently invalidates the oldest.", "src": "https://developers.google.com/identity/protocols/oauth2", "quote": "If the limit is reached, creating a new refresh token automatically invalidates the oldest refresh token without warning."}, {"app": "googlesheets", "field": "gotchas", "text": "Refresh tokens stop working after 6 months unused or if the user revokes access.", "src": "https://developers.google.com/identity/protocols/oauth2", "quote": "The refresh token has not been used for six months."}, {"app": "googlesheets", "field": "gotchas", "text": "Your OAuth redirect URI must exactly match oauth_redirect_uri in the Composio auth config; some defaults still use /api/v1/auth-apps/add.", "src": "https://docs.composio.dev/docs/auth-configuration/custom-auth-configs", "quote": "The redirect URI in your OAuth app must exactly match oauth_redirect_uri in your Composio auth config. Some toolkit defaults still use https://backend.composio.dev/api/v1/auth-apps/add"}, {"app": "googlesheets", "field": "gotchas", "text": "Use separate Google Cloud projects for testing and production, and submit only the production project for verification.", "src": "https://support.google.com/cloud/answer/13464323", "quote": "Please create separate projects for development/testing/staging and production as per the Google OAuth policy."}, {"app": "googlesheets", "field": "gotchas", "text": "Workspace admins can restrict sensitive scopes to OAuth clients they explicitly mark as trusted.", "src": "https://developers.google.com/identity/protocols/oauth2/production-readiness/sensitive-scope-verification", "quote": "Google Workspace organization administrators might restrict access to sensitive scopes to prevent access by OAuth client IDs that the organization doesn't explicitly mark as trusted."}, {"app": "googlesheets", "field": "review", "text": "Google OAuth sensitive scope verification for spreadsheets or spreadsheets.readonly | wait: 3-5 business days (Google's FAQ estimates 10)", "src": "https://developers.google.com/identity/protocols/oauth2/production-readiness/sensitive-scope-verification", "quote": "The sensitive scope verification process typically takes 3-5 business days to complete."}, {"app": "hubspot", "field": "limits", "text": "Before listing: a marketplace-distribution app is limited to 25 installs, excluding developer test accounts.", "src": "https://developers.hubspot.com/docs/apps/developer-platform/build-apps/manage-apps-in-hubspot", "quote": "Marketplace OAuth app prior to listing: can be installed in up to 25 accounts (not including developer test accounts)."}, {"app": "hubspot", "field": "limits", "text": "The 25-install cap applies to apps created or migrated on the Developer Platform from September 22, 2025.", "src": "https://developers.hubspot.com/changelog/new-marketplace-distribution-app-install-limits", "quote": "Starting on September 22nd, 2025, apps that are created or migrated to version 2025.2 are capped at 25 installs until they are listed on the HubSpot Marketplace."}, {"app": "hubspot", "field": "limits", "text": "Private-distribution apps can only be installed in up to 10 allowlisted accounts.", "src": "https://developers.hubspot.com/docs/apps/developer-platform/build-apps/manage-apps-in-hubspot", "quote": "Privately distributed OAuth apps: can be installed in up to 10 allowlisted accounts (not including developer test accounts)."}, {"app": "hubspot", "field": "limits", "text": "Before review, installers see an unverified-app warning and must type \"I accept the risk\" to connect.", "src": "https://developers.hubspot.com/docs/apps/developer-platform/build-apps/manage-apps-in-hubspot", "quote": "Then type I accept the risk, and click Connect to authorize the app."}, {"app": "hubspot", "field": "requirements", "text": "New apps are created with the HubSpot CLI (v7.6.0) via `hs project create`, with redirect URLs and scopes in app-hsmeta.json.", "src": "https://developers.hubspot.com/docs/apps/developer-platform/build-apps/create-an-app", "quote": "Make sure you're using v7.6.0 of the HubSpot CLI before proceeding."}, {"app": "hubspot", "field": "requirements", "text": "Production redirect URLs must use HTTPS.", "src": "https://developers.hubspot.com/docs/api/oauth-quickstart-guide", "quote": "For production applications, https is required."}, {"app": "hubspot", "field": "requirements", "text": "Listing needs at least three active installs in unaffiliated production accounts with activity in the past 30 days.", "src": "https://developers.hubspot.com/docs/apps/developer-platform/list-apps/listing-your-app/app-marketplace-listing-requirements", "quote": "Active installs are the number of unique HubSpot production accounts, unaffiliated with your organization, showing successful app activity within the past 30 days."}, {"app": "hubspot", "field": "requirements", "text": "Listing needs live Terms of Service and Privacy Policy URLs, a support contact, and a public setup guide.", "src": "https://developers.hubspot.com/docs/apps/developer-platform/list-apps/listing-your-app/app-marketplace-listing-requirements", "quote": "URLs for your app's Terms of Service and Privacy Policy must be live and up-to-date."}, {"app": "hubspot", "field": "requirements", "text": "Listed apps must use OAuth as the only auth method and request only the scopes they need.", "src": "https://developers.hubspot.com/docs/apps/developer-platform/list-apps/listing-your-app/app-marketplace-listing-requirements", "quote": "OAuth: your app must use OAuth as its sole authorization method."}, {"app": "hubspot", "field": "requirements", "text": "Listed AI connectors must require user-level permissions or be built with HubSpot's MCP Server.", "src": "https://developers.hubspot.com/docs/apps/developer-platform/list-apps/listing-your-app/app-marketplace-listing-requirements", "quote": "it must require user-level permissions by setting access to user-level or be built with HubSpot's MCP Server."}, {"app": "hubspot", "field": "gotchas", "text": "Access tokens currently expire after 30 minutes, so the refresh flow must work.", "src": "https://developers.hubspot.com/docs/api/oauth-quickstart-guide", "quote": "The access token will expire after the number of seconds given in the expires_in field of the response, currently 30 minutes."}, {"app": "hubspot", "field": "gotchas", "text": "You can submit only one app for listing at a time; extra submissions are rejected automatically.", "src": "https://developers.hubspot.com/docs/apps/developer-platform/list-apps/listing-your-app/app-marketplace-listing-requirements", "quote": "you can only submit one app at a time for approval. Any additional apps submitted while the initial app is being processed will automatically be rejected."}, {"app": "hubspot", "field": "gotchas", "text": "Composio's managed HubSpot app is still awaiting HubSpot approval, so users see a warning; your own app avoids that once listed.", "src": "https://docs.composio.dev/toolkits/hubspot", "quote": "HubSpot shows this warning because the default Composio-managed HubSpot OAuth app is still awaiting HubSpot approval."}, {"app": "hubspot", "field": "gotchas", "text": "Composio's managed app cannot add scopes; a different scope set needs your own app.", "src": "https://docs.composio.dev/toolkits/hubspot", "quote": "You cannot add new scopes to the managed app"}, {"app": "hubspot", "field": "cost", "text": "$0; no listing fee is stated in the listing requirements", "src": "https://developers.hubspot.com/docs/apps/developer-platform/list-apps/listing-your-app/app-marketplace-listing-requirements", "quote": ""}, {"app": "pipedrive", "field": "limits", "text": "Private apps get no Marketplace listing page but can be shared with any Pipedrive company via an unlisted install link.", "src": "https://pipedrive.readme.io/docs/marketplace-creating-a-proper-app", "quote": "Live private apps can be shared with any user/company in Pipedrive via a direct, unlisted installation link"}, {"app": "pipedrive", "field": "requirements", "text": "You need a developer sandbox account to access the Developer Hub.", "src": "https://pipedrive.readme.io/docs/marketplace-app-approval-process", "quote": "Request a developer sandbox account to get access to the Developer Hub"}, {"app": "pipedrive", "field": "requirements", "text": "Both private and public apps must use OAuth 2.0 with working install and uninstall flows.", "src": "https://pipedrive.readme.io/docs/marketplace-creating-a-proper-app", "quote": "All apps (public and private) should manage authentication and authorization using OAuth 2.0 and, subsequently, enable a smooth installation and uninstallation."}, {"app": "pipedrive", "field": "requirements", "text": "Public apps need Terms of Service and Privacy Policy pages and agreement to the Developer Partner Agreement.", "src": "https://pipedrive.readme.io/docs/marketplace-app-approval-process", "quote": "Your app has a Terms of Service webpage with clearly stated rules that users must agree to abide by to use your service"}, {"app": "pipedrive", "field": "requirements", "text": "Public app review needs a demo video, up-to-date test accounts, and 3-5 listing images.", "src": "https://pipedrive.readme.io/docs/marketplace-app-approval-process", "quote": "Your app listing includes 3-5 high-quality images"}, {"app": "pipedrive", "field": "requirements", "text": "The callback URL in requests must match the one entered when registering the app.", "src": "https://pipedrive.readme.io/docs/marketplace-oauth-authorization", "quote": "Authorization code will be sent to that URL (if it matches with the value you entered in the registration form)"}, {"app": "pipedrive", "field": "gotchas", "text": "The app type (private or public) cannot be changed later in Developer Hub.", "src": "https://pipedrive.readme.io/docs/marketplace-creating-a-proper-app", "quote": "NB: Do pick your app type carefully, as it cannot be changed later on Developer Hub."}, {"app": "pipedrive", "field": "gotchas", "text": "Every user in a company installs the app separately; installs are per user.", "src": "https://pipedrive.readme.io/docs/marketplace-creating-a-proper-app", "quote": "Every user in a company needs to install or set up their own apps and integrations."}, {"app": "pipedrive", "field": "gotchas", "text": "Access tokens last 60 minutes; refresh tokens expire after 60 days unused, forcing a full reinstall.", "src": "https://pipedrive.readme.io/docs/marketplace-oauth-authorization", "quote": "refresh_token will expire if it isn't used in 60 days."}, {"app": "pipedrive", "field": "gotchas", "text": "Approved public apps are unlisted by default and must be published manually.", "src": "https://pipedrive.readme.io/docs/marketplace-app-approval-process", "quote": "The app is unlisted from the Marketplace by default after approval."}, {"app": "pipedrive", "field": "gotchas", "text": "Don't click Install and Test in Pipedrive; start the connection from Composio and enter the company subdomain.", "src": "https://docs.composio.dev/toolkits/pipedrive", "quote": "Do not start the user connection by clicking Install and Test inside Pipedrive's OAuth app settings."}, {"app": "pipedrive", "field": "cost", "text": "$0; no submission or listing fee is mentioned", "src": "https://pipedrive.readme.io/docs/marketplace-app-approval-process", "quote": ""}, {"app": "trello", "field": "limits", "text": "300 requests per 10 seconds per API key and 100 per 10 seconds per token.", "src": "https://developer.atlassian.com/cloud/trello/guides/rest-api/rate-limits/", "quote": "There is a limit of 300 requests per 10 seconds for each API key and 100 requests per 10 second interval for each token."}, {"app": "trello", "field": "limits", "text": "Requests to /1/members/ are limited to 100 per 900 seconds.", "src": "https://developer.atlassian.com/cloud/trello/guides/rest-api/rate-limits/", "quote": "Additionally, there is a limit on requests to /1/members/ of 100 requests per 900 seconds."}, {"app": "trello", "field": "requirements", "text": "An API key is tied to a Power-Up created in the admin portal at trello.com/apps/admin.", "src": "https://developer.atlassian.com/cloud/trello/guides/rest-api/authorization/", "quote": "As an API key is tied to a Power-Up, you can visit the https://trello.com/apps/admin page"}, {"app": "trello", "field": "requirements", "text": "The Power-Up must be owned by a Trello Workspace.", "src": "https://developer.atlassian.com/cloud/trello/guides/power-ups/managing-apps/", "quote": "The Trello Workspace that owns the app."}, {"app": "trello", "field": "requirements", "text": "The app form asks for an email, a support email and an author name.", "src": "https://developer.atlassian.com/cloud/trello/guides/power-ups/managing-apps/", "quote": "Support Email We'll use this email when questions arise from users regarding your app"}, {"app": "trello", "field": "requirements", "text": "OAuth 1.0 signing needs the application secret from the Trello Auth tab.", "src": "https://developer.atlassian.com/cloud/trello/guides/rest-api/authorization/", "quote": "You'll also need your application secret (used to sign your requests). That's listed in the Trello Auth tab"}, {"app": "trello", "field": "gotchas", "text": "If the API key has no allowed origins set, no redirect URL works.", "src": "https://developer.atlassian.com/cloud/trello/guides/rest-api/authorization/", "quote": "Note: If your API key has no allowed origins set, then no redirect URL will work."}, {"app": "trello", "field": "gotchas", "text": "Redirects to a return_url not in allowed origins are blocked.", "src": "https://developer.atlassian.com/cloud/trello/guides/rest-api/authorization/", "quote": "If the URL in the return_url parameter does not match one of your API key's allowed origins, the redirect is blocked."}, {"app": "trello", "field": "gotchas", "text": "Token expiration can be 1hour, 1day, 30days or never.", "src": "https://developer.atlassian.com/cloud/trello/guides/rest-api/authorization/", "quote": "1hour, 1day, 30days, never"}, {"app": "trello", "field": "gotchas", "text": "Scopes are only read, write and account.", "src": "https://developer.atlassian.com/cloud/trello/guides/rest-api/authorization/", "quote": "Comma-separated list of one or more of read, write, account."}, {"app": "trello", "field": "gotchas", "text": "By default only admins of the owning Workspace can manage the app.", "src": "https://developer.atlassian.com/cloud/trello/guides/power-ups/managing-apps/", "quote": "By default, apps can only be managed by admins of the Workspace that owns the Power-Up."}, {"app": "trello", "field": "gotchas", "text": "Composio's Trello toolkit uses OAuth 1, not OAuth 2.", "src": "https://docs.composio.dev/toolkits/trello", "quote": "OAuth1"}, {"app": "clickup", "field": "limits", "text": "Rate limit is per token: 100 requests/min on Free, Unlimited and Business plans.", "src": "https://developer.clickup.com/docs/rate-limits", "quote": "The ClickUp API applies rate limits per token."}, {"app": "clickup", "field": "limits", "text": "Business Plus gets 1,000 and Enterprise 10,000 requests per minute per token.", "src": "https://developer.clickup.com/docs/rate-limits", "quote": "Business Plus 1,000 Enterprise / Enterprise Plus 10,000"}, {"app": "clickup", "field": "requirements", "text": "Only Workspace owners or admins can create OAuth apps.", "src": "https://developer.clickup.com/docs/authentication", "quote": "Only Workspace owners or admins can create OAuth apps."}, {"app": "clickup", "field": "requirements", "text": "Create the app under Settings > Apps with a name and redirect URL.", "src": "https://developer.clickup.com/docs/authentication", "quote": "Name the app and add a redirect URL."}, {"app": "clickup", "field": "gotchas", "text": "Access tokens currently do not expire, but ClickUp says this may change.", "src": "https://developer.clickup.com/docs/authentication", "quote": "The access token currently does not expire. This is subject to change."}, {"app": "clickup", "field": "gotchas", "text": "Non-SSL redirect URIs may not be supported in the future.", "src": "https://developer.clickup.com/docs/authentication", "quote": "Non-SSL redirect URIs may not be supported in the future."}, {"app": "clickup", "field": "gotchas", "text": "Users pick one or more Workspaces at authorization; re-authorize to change them.", "src": "https://developer.clickup.com/docs/authentication", "quote": "Users can authorize one or more Workspaces."}, {"app": "outlook", "field": "limits", "text": "Before verification: the consent prompt shows 'Unverified' instead of a publisher name.", "src": "https://learn.microsoft.com/en-us/entra/identity-platform/application-consent-experience", "quote": "If the app isn't publisher verified, \"Unverified\" is displayed instead of a publisher name."}, {"app": "outlook", "field": "requirements", "text": "Register the app in Microsoft Entra ID as at least an Application Developer.", "src": "https://learn.microsoft.com/en-us/entra/identity-platform/quickstart-register-app", "quote": "Sign in to the Microsoft Entra admin center as at least an Application Developer."}, {"app": "outlook", "field": "requirements", "text": "For other organizations, set supported account types to multiple Entra ID tenants, with or without personal Microsoft accounts.", "src": "https://learn.microsoft.com/en-us/entra/identity-platform/quickstart-register-app", "quote": "Ideal for software-as-a-service (SaaS) applications that you intend to provide to multiple organizations."}, {"app": "outlook", "field": "requirements", "text": "Publisher verification needs a verified Microsoft AI Cloud Partner Program (formerly MPN) partner global account ID.", "src": "https://learn.microsoft.com/en-us/entra/identity-platform/publisher-verification-overview", "quote": "The developer must have a Partner One ID for a valid Microsoft AI Cloud Partner Program account that has completed the verification process. The CPP account must be the partner global account (PGA)"}, {"app": "outlook", "field": "requirements", "text": "The app must be registered with a work or school account, not a personal Microsoft account, to be publisher verified.", "src": "https://learn.microsoft.com/en-us/entra/identity-platform/publisher-verification-overview", "quote": "The app that's to be publisher verified must be registered by using a Microsoft Entra work or school account. Apps that are registered by using a Microsoft account can't be publisher verified."}, {"app": "outlook", "field": "requirements", "text": "The publisher domain can't be *.onmicrosoft.com and must match the Partner Center email domain or a DNS-verified custom domain.", "src": "https://learn.microsoft.com/en-us/entra/identity-platform/publisher-verification-overview", "quote": "or be a DNS-verified custom domain that's added to the Microsoft Entra tenant. (NOTE__: the app's publisher domain can't be *.onmicrosoft.com to be publisher verified)"}, {"app": "outlook", "field": "requirements", "text": "The person verifying needs Application Administrator or Cloud Application Administrator in Entra, and Microsoft AI Cloud Partner Program Admin or Accounts Admin in Partner Center, and must sign in with MFA.", "src": "https://learn.microsoft.com/en-us/entra/identity-platform/mark-app-as-publisher-verified", "quote": "The user in Partner Center must have the following roles: Microsoft AI Cloud Partner Program Admin or Accounts Admin."}, {"app": "outlook", "field": "gotchas", "text": "Delegated Mail.Read, Mail.ReadWrite, Mail.Send and Calendars.ReadWrite don't need admin consent, but their application versions do.", "src": "https://learn.microsoft.com/en-us/graph/permissions-reference", "quote": "Allows the app to read mail in all mailboxes without a signed-in user."}, {"app": "outlook", "field": "gotchas", "text": "Delegated Mail.Read is available for consent in personal Microsoft accounts.", "src": "https://learn.microsoft.com/en-us/graph/permissions-reference", "quote": "The Mail.Read delegated permission is available for consent in personal Microsoft accounts."}, {"app": "outlook", "field": "gotchas", "text": "Composio says 'Needs admin approval' errors are a tenant consent setting; a verified publisher helps but doesn't remove admin consent everywhere.", "src": "https://docs.composio.dev/toolkits/outlook", "quote": "It does not remove the admin-consent requirement in every tenant; each Microsoft 365 tenant's user-consent policy and the exact scopes requested still decide whether admin approval is needed."}, {"app": "outlook", "field": "gotchas", "text": "Composio says an admin approving inside the user's OAuth flow may connect the admin's mailbox instead of the user's.", "src": "https://docs.composio.dev/toolkits/outlook", "quote": "If an admin signs in through the same OAuth attempt, that attempt may connect the admin's mailbox instead of the original user's mailbox."}, {"app": "outlook", "field": "gotchas", "text": "Application (app-only) permissions always need tenant admin consent.", "src": "https://learn.microsoft.com/en-us/entra/identity-platform/howto-convert-app-to-be-multi-tenant", "quote": "App-only permissions always require a tenant administrator's consent."}, {"app": "outlook", "field": "gotchas", "text": "Tenant admins can turn off user consent, which makes admin consent mandatory for every app in that tenant.", "src": "https://learn.microsoft.com/en-us/entra/identity-platform/howto-convert-app-to-be-multi-tenant", "quote": "If this capability is disabled, admin consent is always required for the application to be used in the tenant."}, {"app": "outlook", "field": "gotchas", "text": "Microsoft recommends tenants allow user consent only for apps from verified publishers.", "src": "https://learn.microsoft.com/en-us/entra/identity/enterprise-apps/configure-user-consent", "quote": "we recommend that you allow user consent only for applications that have been published by a verified publisher."}, {"app": "outlook", "field": "gotchas", "text": "Client secrets last 24 months at most, and Microsoft recommends under 12 months.", "src": "https://learn.microsoft.com/en-us/entra/identity-platform/how-to-add-credentials", "quote": "Client secret lifetime is limited to two years (24 months) or less."}, {"app": "outlook", "field": "gotchas", "text": "Refresh tokens last 90 days by default, or 24 hours for single-page app redirect URIs.", "src": "https://learn.microsoft.com/en-us/entra/identity-platform/refresh-tokens", "quote": "Refresh tokens sent to a redirect URI registered as spa expire after 24 hours."}, {"app": "outlook", "field": "cost", "text": "$0: Microsoft doesn't charge for publisher verification and no license is needed", "src": "https://learn.microsoft.com/en-us/entra/identity-platform/publisher-verification-overview", "quote": "Microsoft doesn't charge developers for publisher verification. No license is required to become a verified publisher."}, {"app": "zoom", "field": "limits", "text": "Before review: private apps can only be shared with members of your own Zoom account.", "src": "https://developers.zoom.us/docs/distribute/sharing-private-and-beta-apps", "quote": "You can only share private apps with members within your Zoom account."}, {"app": "zoom", "field": "limits", "text": "Beta apps can reach limited external users only after Zoom approves sharing the authorization URL.", "src": "https://developers.zoom.us/docs/distribute/sharing-private-and-beta-apps", "quote": "we allow you to share beta apps to a limited number of users outside your Zoom account. You must get approval from Zoom to share the authorization URL outside your account."}, {"app": "zoom", "field": "limits", "text": "Approved beta authorization URLs last 4 weeks, with up to two 4-week extensions.", "src": "https://developers.zoom.us/docs/distribute/sharing-private-and-beta-apps", "quote": "We issue authorization URLs for a period of 4 weeks after which you can request two additional 4-week extensions."}, {"app": "zoom", "field": "limits", "text": "Beta sharing caps: 10 additions for account-level apps and 100 for user-level apps.", "src": "https://developers.zoom.us/docs/distribute/sharing-private-and-beta-apps", "quote": "The maximum number of additions for a private account-level application is 10. The maximum number of additions for a private user-level application is 100."}, {"app": "zoom", "field": "requirements", "text": "Published apps must provide Terms of Use, a privacy policy and user support.", "src": "https://developers.zoom.us/docs/distribute", "quote": "at minimum: a Terms of Use, Privacy Policy, Self-Serve Documentation, and Support URL as part of the Zoom Marketplace Developer Agreement."}, {"app": "zoom", "field": "requirements", "text": "An OAuth redirect URL and an OAuth allow list are required.", "src": "https://developers.zoom.us/docs/build-flow/basic-info/oauth-info", "quote": "OAuth Allow Lists (Required): Limits redirects to specified URLs"}, {"app": "zoom", "field": "gotchas", "text": "Zoom answers external beta sharing requests within 3-4 business days.", "src": "https://developers.zoom.us/docs/distribute/sharing-private-and-beta-apps", "quote": "A member of the Zoom app review team responds to your request no longer than 3-4 business days."}, {"app": "zoom", "field": "gotchas", "text": "Development and production OAuth values differ, so configure both.", "src": "https://developers.zoom.us/docs/build-flow/basic-info/oauth-info", "quote": "The OAuth values differ in the development and production environments."}, {"app": "zoom", "field": "gotchas", "text": "Loopback or dev redirect URLs in production may be rejected in review.", "src": "https://developers.zoom.us/docs/build-flow/basic-info/oauth-info", "quote": "These resources are not suitable for production-ready end users and may be rejected during the marketplace publishing review."}, {"app": "zoom", "field": "gotchas", "text": "Access tokens last one hour; refresh tokens expire after 90 days.", "src": "https://developers.zoom.us/docs/integrations/oauth", "quote": "Refresh tokens expire after 90 days."}, {"app": "zoom", "field": "gotchas", "text": "Zoom enables no scopes by default; add each one in the Scopes tab.", "src": "https://composio.dev/auth/zoom", "quote": "By default, Zoom does not enable any scopes on your application. You need to enable the ones you require manually."}, {"app": "zoom", "field": "gotchas", "text": "Unlisted apps still go through review and still need full listing metadata.", "src": "https://developers.zoom.us/docs/build-flow/before-you-build", "quote": "The app will fail app review if it doesn't have the required meta data."}, {"app": "zoom", "field": "review", "text": "Zoom App Marketplace review, including a security review | wait: not stated (varies with app quality)", "src": "https://developers.zoom.us/docs/distribute/app-review-process", "quote": "An app's review time varies based on app quality, usability, quantity and function of features, and clarity of information"}, {"app": "intercom", "field": "limits", "text": "Before approval the app is private and can only be used by you and your team.", "src": "https://developers.intercom.com/docs/publish-to-the-app-store/review-publish-your-app", "quote": "During this process, your app will be private and can only be used by you and your team."}, {"app": "intercom", "field": "limits", "text": "Development workspaces cap at 20 users, can't send outbound email, and can't become production workspaces.", "src": "https://developers.intercom.com/docs/build-an-integration/getting-started", "quote": "A maximum of 20 users/leads (if you have more than 20 users/leads, the oldest extras will be archived automatically on a regular basis)."}, {"app": "intercom", "field": "requirements", "text": "Public app developers must create a development workspace to build and publish the app.", "src": "https://developers.intercom.com/docs/build-an-integration/getting-started", "quote": "If you are building a public app to share with multiple customers, you must create a new development workspace to develop and publish the app."}, {"app": "intercom", "field": "requirements", "text": "OAuth redirect URLs must use HTTPS.", "src": "https://developers.intercom.com/docs/build-an-integration/learn-more/authentication/setting-up-oauth", "quote": "Redirect URLs must use HTTPS"}, {"app": "intercom", "field": "requirements", "text": "Review needs a video showing OAuth install, end-to-end functionality, and OAuth uninstall.", "src": "https://developers.intercom.com/docs/publish-to-the-app-store/review-publish-your-app", "quote": "The purpose of the video is to understand if the OAuth flow works and if your app meets our app guidelines."}, {"app": "intercom", "field": "requirements", "text": "Requested scopes are checked against what the app does.", "src": "https://developers.intercom.com/docs/publish-to-the-app-store/review-publish-your-app", "quote": "It is also to determine whether the scopes match the required functionality of the app"}, {"app": "intercom", "field": "requirements", "text": "Unlisted apps must be installed from your own product or website.", "src": "https://developers.intercom.com/docs/publish-to-the-app-store/review-publish-your-app", "quote": "An unlisted app is a public app that is available for anyone to install but is not listed in the App Store: It must be installed via your own product or website."}, {"app": "intercom", "field": "gotchas", "text": "OAuth is off until you tick \"Use OAuth\" on the app's Authentication page.", "src": "https://developers.intercom.com/docs/build-an-integration/learn-more/authentication/setting-up-oauth", "quote": "To start, tick the Use OAuth option on your Authentication page in the Developer Hub."}, {"app": "intercom", "field": "gotchas", "text": "In EU and AU, development-workspace apps can't be installed into paid workspaces.", "src": "https://developers.intercom.com/docs/build-an-integration/getting-started", "quote": "not recommended if your account is in the Europe or Australia regions because you will not be able to install development workspace apps into your paid workspace."}, {"app": "intercom", "field": "review", "text": "Intercom app review (required for both listed and unlisted public apps) | wait: Up to 7 business days", "src": "https://developers.intercom.com/docs/publish-to-the-app-store/review-publish-your-app", "quote": "Both unlisted and listed apps must be submitted for review."}, {"app": "intercom", "field": "cost", "text": "$0; development workspaces are free and no review fee is mentioned", "src": "https://developers.intercom.com/docs/build-an-integration/getting-started", "quote": "Development workspaces are free and intended for development purposes only."}, {"app": "reddit", "field": "limits", "text": "Without a separate agreement: no commercial use, and no research beyond the rate limits.", "src": "https://redditinc.com/policies/data-api-terms", "quote": "If you are interested in using the Data APIs for commercial purposes, research in excess of rate limits, or for any use that is not expressly permitted under the Data API Terms"}, {"app": "reddit", "field": "limits", "text": "You may not derive revenue from the Data APIs without Reddit's express written approval.", "src": "https://redditinc.com/policies/data-api-terms", "quote": "derive revenues from the use or provision of the Data APIs, whether for direct commercial or monetary gain unless there is express written approval from Reddit"}, {"app": "reddit", "field": "requirements", "text": "You must provide up-to-date identification and contact details to access the Data APIs.", "src": "https://redditinc.com/policies/data-api-terms", "quote": "In order to access the Data APIs, you are required to provide identification information (e.g., contact details). This information must be up to date and accurate at all times."}, {"app": "reddit", "field": "requirements", "text": "The redirect_uri in requests must exactly match the one registered on the app.", "src": "https://github.com/reddit-archive/reddit/wiki/OAuth2", "quote": "Yes, you need it here again, and yes, it must match exactly."}, {"app": "reddit", "field": "requirements", "text": "Use a web app type to get a client secret; installed apps get none.", "src": "https://github.com/reddit-archive/reddit/wiki/OAuth2", "quote": "Cannot keep a secret, and therefore, does not receive one."}, {"app": "reddit", "field": "requirements", "text": "Reddit's archived API rules require a unique, descriptive User-Agent.", "src": "https://github.com/reddit-archive/reddit/wiki/API", "quote": "Change your client's User-Agent string to something unique and descriptive,"}, {"app": "reddit", "field": "gotchas", "text": "Bearer tokens expire after 1 hour; request duration=permanent to get a refresh token.", "src": "https://github.com/reddit-archive/reddit/wiki/OAuth2", "quote": "All bearer tokens expire after 1 hour. If you indicate you need permanent access to a user's account, you will additionally receive a refresh_token"}, {"app": "reddit", "field": "gotchas", "text": "The terms ban using User Content to train ML or AI models without rightsholders' permission.", "src": "https://redditinc.com/policies/data-api-terms", "quote": "such as for training a machine learning or AI model, without the express permission of rightsholders in the applicable User Content"}, {"app": "reddit", "field": "gotchas", "text": "You must delete data not needed for your approved use case.", "src": "https://redditinc.com/policies/data-api-terms", "quote": "beyond your approved use case, and you must immediately delete any data not required for it"}, {"app": "reddit", "field": "gotchas", "text": "Reddit says Devvit is now its primary way to build apps, not the Data API.", "src": "https://developers.reddit.com/docs/guides/migrate/public-api", "quote": "Devvit is now the primary way to develop Reddit extensions"}, {"app": "reddit", "field": "review", "text": "Separate agreement with Reddit for commercial use or use beyond the Data API Terms | wait: not stated", "src": "https://redditinc.com/policies/data-api-terms", "quote": "or for any use that is not expressly permitted under the Data API Terms, then you will need to enter into a separate agreement with Reddit."}, {"app": "reddit", "field": "cost", "text": "No published price; Reddit reserves the right to charge fees", "src": "https://redditinc.com/policies/data-api-terms", "quote": "Reddit reserves the right to charge fees for future use or access to the Data APIs, rates to be determined at Reddit's sole discretion."}, {"app": "figma", "field": "limits", "text": "Before publishing: a draft app can only be tested by you and your plan's admins.", "src": "https://developers.figma.com/docs/rest-api/oauth-apps/", "quote": "While in draft, you and admins for your plan can test your OAuth app."}, {"app": "figma", "field": "requirements", "text": "The app must be associated with a team or organization; its users don't need to belong to it.", "src": "https://developers.figma.com/docs/rest-api/oauth-apps/", "quote": "The OAuth app must be associated with a team or organization. note Note: Users of your application don’t need to be a part of the team or organization you select."}, {"app": "figma", "field": "requirements", "text": "Public apps need testing instructions and any trial access or login credentials the reviewer needs.", "src": "https://developers.figma.com/docs/rest-api/oauth-apps/", "quote": "If necessary for working with your application, provide a free trial URL or login credentials that the OAuth app reviewer can use to access your application."}, {"app": "figma", "field": "requirements", "text": "Apps need an accurate name, description and an icon that matches your brand.", "src": "https://help.figma.com/hc/en-us/articles/34963247780247", "quote": "Your Figma Community App must include an accurate name and description, and an icon that matches your application’s brand."}, {"app": "figma", "field": "requirements", "text": "Provide a support contact and keep it accurate.", "src": "https://help.figma.com/hc/en-us/articles/34963247780247", "quote": "Please ensure that your contact information is accurate and complete for users in the event they have any questions, support issues, or feedback."}, {"app": "figma", "field": "requirements", "text": "Apps must not bulk-export file content or index files through the projects endpoints.", "src": "https://help.figma.com/hc/en-us/articles/34963247780247", "quote": "Figma Community Apps may not use the projects endpoints to enumerate the files in an organization/team."}, {"app": "figma", "field": "requirements", "text": "Users must authorize in a web browser; WebViews are not supported.", "src": "https://developers.figma.com/docs/rest-api/oauth-apps/", "quote": "the user must access the authentication URL using a web browser, not an embedded WebView inside your application. WebView access to the Figma OAuth flow is not supported."}, {"app": "figma", "field": "gotchas", "text": "The client secret is shown only once when you create the app.", "src": "https://developers.figma.com/docs/rest-api/oauth-apps/", "quote": "Copy the Client ID and Client Secret for your OAuth app and store them securely. This is the only opportunity you have to obtain the Client Secret."}, {"app": "figma", "field": "gotchas", "text": "Any change to a published public app needs another review.", "src": "https://developers.figma.com/docs/rest-api/oauth-apps/", "quote": "In the case of published public apps, changes to configuration will require your OAuth app to be re-reviewed."}, {"app": "figma", "field": "gotchas", "text": "files:read and file_read are deprecated; apps must use granular scopes.", "src": "https://developers.figma.com/docs/rest-api/republish-oauth-apps/", "quote": "We're removing the deprecated files:read and file_read scopes."}, {"app": "figma", "field": "gotchas", "text": "Existing apps marked 'Update required' must be republished to meet the November 17, 2025 rules.", "src": "https://developers.figma.com/docs/rest-api/republish-oauth-apps/", "quote": "The changes went into effect on November 17, 2025. If you haven't re-published your app yet, you'll need to do so to meet these requirements."}, {"app": "figma", "field": "gotchas", "text": "Write scopes like teams:write and folders:write work only in private apps on Enterprise.", "src": "https://developers.figma.com/docs/rest-api/scopes/", "quote": "teams:write Create teams. Available only to private OAuth apps in an Enterprise plan."}, {"app": "figma", "field": "gotchas", "text": "file_variables:read and :write are Enterprise-only scopes.", "src": "https://developers.figma.com/docs/rest-api/scopes/", "quote": "file_variables:read Read variables in files. Note: Enterprise plan only."}, {"app": "figma", "field": "gotchas", "text": "Authorization codes expire after 30 seconds.", "src": "https://developers.figma.com/docs/rest-api/oauth-apps/", "quote": "Note: Authentication codes expire 30 seconds after being issued."}, {"app": "figma", "field": "gotchas", "text": "Access tokens last 90 days; refreshing invalidates the previous token because Figma keeps one per user per app.", "src": "https://developers.figma.com/docs/rest-api/oauth-apps/", "quote": "Figma only maintains one access token per app for a user, so when you refresh an access token, the previous access token stops working."}, {"app": "figma", "field": "gotchas", "text": "OAuth rate limits are tracked per user, per plan, per app.", "src": "https://developers.figma.com/docs/rest-api/rate-limits/", "quote": "For OAuth apps, rate limits are tracked on a per-user, per-plan, per-app basis."}, {"app": "figma", "field": "gotchas", "text": "Users on View or Collab seats get up to 20 Tier 1 file requests a month, possibly fewer under load.", "src": "https://developers.figma.com/docs/rest-api/rate-limits/", "quote": "For View and Collab seats, requests are limited up to the given amount. Depending on traffic and demand, the actual limit may be lower."}, {"app": "figma", "field": "review", "text": "Figma review of a public OAuth app (testing instructions, reviewer access) | wait: not stated; Figma says it varies with volume", "src": "https://help.figma.com/hc/en-us/articles/34963247780247", "quote": "Approval times vary depending on current volume and the team’s availability."}, {"app": "confluence", "field": "limits", "text": "Before sharing: a new 3LO app is private, so only you can install and use it.", "src": "https://developer.atlassian.com/cloud/confluence/oauth-2-3lo-apps/", "quote": "When you create an OAuth 2.0 (3LO) app, it's private by default. This means that only you can install and use it."}, {"app": "confluence", "field": "limits", "text": "Before approval: users installing an unapproved integration are warned it hasn't been reviewed by Atlassian.", "src": "https://developer.atlassian.com/cloud/confluence/oauth-2-3lo-apps/", "quote": "Users trying to install an unapproved OAuth 2.0 integration are warned that the app has not yet been reviewed by Atlassian."}, {"app": "confluence", "field": "limits", "text": "Sharing doesn't list the app on the Marketplace; you must send the authorization URL to every user.", "src": "https://developer.atlassian.com/cloud/confluence/oauth-2-3lo-apps/", "quote": "You'll have to send the link to all the users you want to grant access to. Enabling sharing doesn't make your app available on the Atlassian Marketplace ."}, {"app": "confluence", "field": "requirements", "text": "Create an 'OAuth 2.0 integration' in the developer console, configure OAuth 2.0 (3LO) and add Confluence API scopes under Permissions.", "src": "https://developer.atlassian.com/cloud/confluence/oauth-2-3lo-apps/", "quote": "In the Developer console, select the Create dropdown and choose OAuth 2.0 integration to create an OAuth 2.0 (3LO) app."}, {"app": "confluence", "field": "requirements", "text": "Turn on 'Enable sharing' under Distribution before anyone else can authorize the app.", "src": "https://developer.atlassian.com/cloud/confluence/oauth-2-3lo-apps/", "quote": "If you want to distribute your app to other users, you must enable sharing."}, {"app": "confluence", "field": "requirements", "text": "Apps that store personal data must report those account IDs to the Personal data reporting API.", "src": "https://developer.atlassian.com/cloud/confluence/user-privacy-developer-guide/", "quote": "All apps storing personal data must report user personal data, using the Personal data reporting API ."}, {"app": "confluence", "field": "requirements", "text": "Report each stored account once per cycle period (7 days by default, or per the Cycle-Period header), and not more often.", "src": "https://developer.atlassian.com/cloud/confluence/user-privacy-developer-guide/", "quote": "you should not send reports more frequently than the cycle period for each accountId ."}, {"app": "confluence", "field": "requirements", "text": "Erase or refresh a user's data when the reporting API says so; 3LO apps call POST https://api.atlassian.com/app/report-accounts/.", "src": "https://developer.atlassian.com/cloud/confluence/user-privacy-developer-guide/", "quote": "Report accounts for OAuth 2.0 authorization code grants (3LO) apps POST https://api.atlassian.com/app/report-accounts/"}, {"app": "confluence", "field": "requirements", "text": "For Marketplace approval, give reviewers access to a test instance of your software.", "src": "https://developer.atlassian.com/platform/marketplace/knowledge-base/listing-a-third-party-integration-on-the-atlassian-marketplace/", "quote": "In order to test the integration we will need access to a test instance of your software so we can run through the set up and configuration."}, {"app": "confluence", "field": "gotchas", "text": "Add offline_access to the scope to get a refresh token at all.", "src": "https://developer.atlassian.com/cloud/confluence/oauth-2-3lo-apps/", "quote": "To get a refresh token in your initial authorization flow, add offline_access to the scope parameter of the authorization URL."}, {"app": "confluence", "field": "gotchas", "text": "Refresh tokens rotate; store the new one every time, since the old one is disabled.", "src": "https://developer.atlassian.com/cloud/confluence/oauth-2-3lo-apps/", "quote": "You receive a new refresh token as well and the refresh token you used for the request is disabled."}, {"app": "confluence", "field": "gotchas", "text": "A refresh token expires after 90 days of inactivity, and then the user must re-authorize.", "src": "https://developer.atlassian.com/cloud/confluence/oauth-2-3lo-apps/", "quote": "Inactivity expiry time 90 days A rotating refresh token expires if the user is inactive for this period."}, {"app": "confluence", "field": "gotchas", "text": "Changing scopes forces users who already consented to consent again.", "src": "https://developer.atlassian.com/cloud/confluence/oauth-2-3lo-apps/", "quote": "Note that users who previously consented to the scopes will need to re-consent to the new scopes."}, {"app": "confluence", "field": "gotchas", "text": "API calls go to api.atlassian.com/ex/confluence/{cloudid}; get the cloudid from accessible-resources.", "src": "https://developer.atlassian.com/cloud/confluence/oauth-2-3lo-apps/", "quote": "https://api.atlassian.com/ex/confluence/{cloudid}/{api}"}, {"app": "confluence", "field": "gotchas", "text": "Site-scoped grants make users pick one site per consent, so multi-site installs mean repeating the flow.", "src": "https://developer.atlassian.com/cloud/confluence/oauth-2-3lo-apps/", "quote": "The consent screen currently requires the user to select the site where they want to install the app."}, {"app": "confluence", "field": "gotchas", "text": "Admins can't revoke one user's grant from Connected Apps; they can only uninstall the app.", "src": "https://developer.atlassian.com/cloud/confluence/oauth-2-3lo-apps/", "quote": "An admin can't revoke a user's access to an app through the Connected Apps user screen."}, {"app": "salesforce", "field": "limits", "text": "Without passing security review you can't list on AgentExchange or distribute your solution there.", "src": "https://developer.salesforce.com/docs/platform/isvforce/guide/security-review-how-it-works.html", "quote": "Not Approved: The security review team detected security issues in your solution. You can’t list your solution on AgentExchange or distribute it to customers."}, {"app": "salesforce", "field": "limits", "text": "A customer org admin may need to install or approve your app before users can connect.", "src": "https://docs.composio.dev/toolkits/salesforce", "quote": "These errors usually mean Salesforce is blocking OAuth because the connected app has not been installed or approved for the org."}, {"app": "salesforce", "field": "requirements", "text": "Creating Connected Apps is restricted as of Spring '26; Salesforce recommends External Client Apps instead.", "src": "https://developer.salesforce.com/docs/platform/api-rest/guide/intro-oauth-and-connected-apps.html", "quote": "Creating connected apps is restricted as of Spring ‘26. You can continue to use existing connected apps during and after Spring ‘26. However, we recommend using external client apps instead."}, {"app": "salesforce", "field": "requirements", "text": "Creating a Connected App now needs Salesforce Support to enable an org permission, once per org.", "src": "https://developer.salesforce.com/docs/platform/sfdx-dev/guide/sfdx-dev-auth-connected-app.html", "quote": "If you need to create a connected app, Salesforce Customer Support must enable an org perm in your org. This is a one-time process per org."}, {"app": "salesforce", "field": "requirements", "text": "Security review requires ISV Partner Program enrollment, a Lightning Ready solution and a Partner Console provider profile.", "src": "https://developer.salesforce.com/docs/platform/isvforce/guide/security-review-how-it-works.html", "quote": "Enroll your solution in the ISV Partner Program. Certify that your solution is Lightning Ready ."}, {"app": "salesforce", "field": "requirements", "text": "API-only submissions need a Developer Edition org, credentials for external components, DAST scan reports, false-positive notes if any, and solution documentation.", "src": "https://developer.salesforce.com/docs/platform/isvforce/guide/security-review-required-materials.html", "quote": "URLs and login credentials for external components requiring authentication"}, {"app": "salesforce", "field": "requirements", "text": "Reviewers test external web apps and services your solution uses, following where Salesforce data goes.", "src": "https://developer.salesforce.com/docs/platform/isvforce/guide/security-review-required-materials.html", "quote": "To determine testing scope, we typically use a follow-the-data approach. Wherever the customer goes, we go."}, {"app": "salesforce", "field": "gotchas", "text": "OAUTH_APPROVAL_ERROR_GENERIC or 'app must be installed into org' means an org admin must approve or install the app.", "src": "https://docs.composio.dev/toolkits/salesforce", "quote": "Ask a Salesforce org admin to approve or install the connected app."}, {"app": "salesforce", "field": "gotchas", "text": "Distributing an External Client App to other orgs is done through a second-generation managed package.", "src": "https://trailhead.salesforce.com/content/learn/modules/external-client-app-basics/package-and-distribute-external-client-apps", "quote": "perhaps the greatest advantage of using External Client Apps is the ability to distribute them with second-generation managed packages."}, {"app": "salesforce", "field": "gotchas", "text": "OAuth consumer credentials are global settings that must stay in a long-lived org, not in the package.", "src": "https://trailhead.salesforce.com/content/learn/modules/external-client-app-basics/package-and-distribute-external-client-apps", "quote": "These settings must not be packaged but stored on a non-ephemeral org that exists throughout the life of all packages."}, {"app": "salesforce", "field": "gotchas", "text": "Refresh token expiry is set by the app's OAuth policy, so check it before going live.", "src": "https://developer.salesforce.com/docs/platform/sfdx-dev/guide/sfdx-dev-auth-connected-app.html", "quote": "In the OAuth Policies section, for the Refresh Token Policy field, click Expire refresh token after: and enter 90 days or less."}, {"app": "salesforce", "field": "cost", "text": "Security review fee for paid apps; no fee if you distribute for free (amount not on current docs page)", "src": "https://developer.salesforce.com/docs/platform/isvforce/guide/security-review-how-it-works.html", "quote": "Use the security review submission interface to share your solution and required materials and to pay the security review fee. If you plan to distribute your solution for free, you don’t pay the fee."}, {"app": "airtable", "field": "limits", "text": "Without privacy policy and terms of service URLs, other users cannot authorize the integration.", "src": "https://airtable.com/developers/web/guides/oauth-integrations", "quote": "must be provided before sharing your OAuth integration with other users - if you have not provided them, other users will not be able to authorize your integration."}, {"app": "airtable", "field": "limits", "text": "API limit is 5 requests per second per base; a 429 means waiting 30 seconds.", "src": "https://airtable.com/developers/web/api/rate-limits", "quote": "The API is limited to 5 requests per second per base."}, {"app": "airtable", "field": "requirements", "text": "Register at airtable.com/create/oauth with a unique name and a valid redirect URL.", "src": "https://airtable.com/developers/web/guides/oauth-integrations", "quote": "Give your integration a unique name and register a valid redirect URL and click ‘Register integration’."}, {"app": "airtable", "field": "requirements", "text": "Redirect URIs must use HTTPS, except localhost.", "src": "https://airtable.com/developers/web/api/oauth-reference", "quote": "Redirect URIs must use the HTTPS scheme. Localhost URIs are an exception, and may use the HTTP scheme."}, {"app": "airtable", "field": "requirements", "text": "Privacy policy URL and terms of service URL are required before sharing.", "src": "https://airtable.com/developers/web/guides/oauth-integrations", "quote": "Privacy policy URL (required to share integration)"}, {"app": "airtable", "field": "requirements", "text": "Generate a client secret if token requests come from a server.", "src": "https://airtable.com/developers/web/guides/oauth-integrations", "quote": "You should generate a client secret if you will be issuing token requests from a server."}, {"app": "airtable", "field": "gotchas", "text": "Access tokens expire after 60 minutes.", "src": "https://airtable.com/developers/web/api/oauth-reference", "quote": "Access tokens expire after 60 minutes."}, {"app": "airtable", "field": "gotchas", "text": "Refresh tokens are valid for 60 days; unused ones force re-authorization.", "src": "https://airtable.com/developers/web/api/oauth-reference", "quote": "Refresh tokens are valid for 60 days. If the refresh token is not used in this time, the authorization is effectively revoked - the user will need to re-authorize"}, {"app": "airtable", "field": "gotchas", "text": "Refreshing invalidates the previous access and refresh tokens.", "src": "https://airtable.com/developers/web/api/oauth-reference", "quote": "When a refresh token is exchanged for an access token, the previous access and refresh tokens are invalidated"}, {"app": "airtable", "field": "gotchas", "text": "The code exchange must happen within 10 minutes of the authorization request.", "src": "https://airtable.com/developers/web/api/oauth-reference", "quote": "This request must be made within 10 minutes of the authorization request."}, {"app": "airtable", "field": "gotchas", "text": "Users choose which bases to grant and can change that at any time.", "src": "https://airtable.com/developers/web/guides/oauth-integrations", "quote": "These may change at any time (e.g. the user could add an additional base, or revoke access to one)."}, {"app": "airtable", "field": "gotchas", "text": "Frequent invalid refresh requests may get the token revoked.", "src": "https://airtable.com/developers/web/api/oauth-reference", "quote": "Note: frequent invalid refresh requests may result in token revocation."}, {"app": "youtube", "field": "limits", "text": "Before approval: Testing mode is limited to 100 test users listed on the consent screen.", "src": "https://support.google.com/cloud/answer/15549945", "quote": "Projects configured with a publishing status of Testing are limited to up to 100 test users listed in the OAuth consent screen."}, {"app": "youtube", "field": "limits", "text": "Before approval: test-user authorizations and refresh tokens expire 7 days after consent.", "src": "https://support.google.com/cloud/answer/15549945", "quote": "Authorizations by a test user will expire seven days from the time of consent. If your OAuth client requests an offline access type and receives a refresh token, that token will also expire."}, {"app": "youtube", "field": "limits", "text": "Before approval: an In-production app requesting unapproved sensitive or restricted scopes shows the unverified app screen.", "src": "https://support.google.com/cloud/answer/15549945", "quote": "Google will display an Unverified apps warning message if your project's OAuth clients request authorization of scopes considered sensitive or restricted before your project has completed verification"}, {"app": "youtube", "field": "limits", "text": "Before approval: unverified apps are capped at 100 new users for the lifetime of the project, and the cap cannot be reset.", "src": "https://support.google.com/cloud/answer/13463817", "quote": "unverified apps that are accessing restricted or sensitive scopes have a 100 new-user cap restriction"}, {"app": "youtube", "field": "limits", "text": "Before a quota audit: default quota is 100 search.list calls, 100 videos.insert calls and 10,000 units a day for all other endpoints.", "src": "https://developers.google.com/youtube/data/guides/quota_and_compliance_audits", "quote": "default quota allocation of 100 search.list calls, 100 videos.insert calls, and 10,000 units per day combined for all other endpoints"}, {"app": "youtube", "field": "requirements", "text": "Verify ownership of your authorized domains in Google Search Console.", "src": "https://developers.google.com/identity/protocols/oauth2/production-readiness/sensitive-scope-verification", "quote": "Verify ownership of your project's authorized domains within the Google Search Console ."}, {"app": "youtube", "field": "requirements", "text": "Host a public home page and a privacy policy on the same domain, both linked from the consent screen.", "src": "https://developers.google.com/identity/protocols/oauth2/production-readiness/sensitive-scope-verification", "quote": "The privacy policy must be visible to users, hosted within the same domain as your application's home page, and linked to on the OAuth consent screen"}, {"app": "youtube", "field": "requirements", "text": "The privacy policy must disclose how the app accesses, uses, stores, or shares Google user data.", "src": "https://developers.google.com/identity/protocols/oauth2/production-readiness/sensitive-scope-verification", "quote": "The privacy policy must disclose the manner in which your application accesses, uses, stores, or shares Google user data."}, {"app": "youtube", "field": "requirements", "text": "Give a written justification for each sensitive scope, including why a narrower scope is not enough.", "src": "https://developers.google.com/identity/protocols/oauth2/production-readiness/sensitive-scope-verification", "quote": "Prepare a detailed justification for each requested sensitive scope, as well as an explanation for why a narrower scope isn't sufficient."}, {"app": "youtube", "field": "requirements", "text": "Submit an unlisted YouTube video showing the consent flow, the client ID in the address bar, and each scope in use.", "src": "https://developers.google.com/identity/protocols/oauth2/production-readiness/sensitive-scope-verification", "quote": "Upload the video to YouTube Studio and set its Visibility as Unlisted ."}, {"app": "youtube", "field": "requirements", "text": "You must publish your branding before you can request verification for data access.", "src": "https://developers.google.com/identity/protocols/oauth2/production-readiness/sensitive-scope-verification", "quote": "Note that you must have a published branding status before you can request verification for data access."}, {"app": "youtube", "field": "requirements", "text": "More quota than the default requires passing a YouTube API Services compliance audit.", "src": "https://developers.google.com/youtube/data/guides/quota_and_compliance_audits", "quote": "If you would like to request additional quota beyond the default allocation, you must first complete an audit to show that your project is in compliance with the YouTube API Services Terms of Service"}, {"app": "youtube", "field": "requirements", "text": "Internal-only apps (Workspace-owned project, Internal audience) skip verification and the 100-user cap but only work in that org.", "src": "https://support.google.com/cloud/answer/13464323", "quote": "Your app will not be subject to the unverified app screen or the 100-user cap if it's designated as internal-only. However, only users in the Workspace or Cloud Identity organization will be able"}, {"app": "youtube", "field": "gotchas", "text": "Google lists deleting a YouTube video as an example of a sensitive scope.", "src": "https://developers.google.com/identity/protocols/oauth2/production-readiness/sensitive-scope-verification", "quote": "Examples of sensitive scopes include reading events stored in Google Calendar, storing a new contact in Google Contacts, or deleting a YouTube video."}, {"app": "youtube", "field": "gotchas", "text": "No YouTube Data API scope appears on Google's restricted scope list.", "src": "https://support.google.com/cloud/answer/13464325", "quote": "The following scopes are categorized as \"restricted\""}, {"app": "youtube", "field": "gotchas", "text": "YouTube runs periodic audits and requires a form if your company changes control.", "src": "https://developers.google.com/youtube/data/guides/quota_and_compliance_audits", "quote": "We conduct periodic audits to ensure quality, improve our products and services, and verify your compliance"}, {"app": "youtube", "field": "gotchas", "text": "Google's FAQ estimates sensitive scope verification at 10 business days, which is longer than the 3-5 days on the developer page.", "src": "https://support.google.com/cloud/answer/13463817", "quote": "10 Business days"}, {"app": "youtube", "field": "gotchas", "text": "Limits apply to refresh tokens: 100 per Google Account per client ID, and creating a new one silently invalidates the oldest.", "src": "https://developers.google.com/identity/protocols/oauth2", "quote": "There is currently a limit of 100 refresh tokens per Google Account per OAuth 2.0 client ID. If the limit is reached, creating a new refresh token automatically invalidates the oldest"}, {"app": "youtube", "field": "gotchas", "text": "Refresh tokens stop working after 6 months unused or if the user revokes access.", "src": "https://developers.google.com/identity/protocols/oauth2", "quote": "The refresh token has not been used for six months."}, {"app": "youtube", "field": "gotchas", "text": "Your OAuth redirect URI must exactly match oauth_redirect_uri in the Composio auth config; some defaults still use /api/v1/auth-apps/add.", "src": "https://docs.composio.dev/docs/auth-configuration/custom-auth-configs", "quote": "The redirect URI in your OAuth app must exactly match `oauth_redirect_uri` in your Composio auth config. Some toolkit defaults still use `https://backend.composio.dev/api/v1/auth-apps/add`"}, {"app": "youtube", "field": "gotchas", "text": "Use separate Google Cloud projects for testing and production, and submit only the production project for verification.", "src": "https://support.google.com/cloud/answer/13464323", "quote": "Please create separate projects for development/testing/staging and production as per the Google OAuth policy ."}, {"app": "youtube", "field": "gotchas", "text": "Workspace admins can restrict sensitive scopes to OAuth clients they explicitly mark as trusted.", "src": "https://developers.google.com/identity/protocols/oauth2/production-readiness/sensitive-scope-verification", "quote": "Google Workspace organization administrators might restrict access to sensitive scopes to prevent access by OAuth client IDs that the organization doesn't explicitly mark as trusted."}, {"app": "youtube", "field": "review", "text": "Google OAuth sensitive scope verification; a YouTube compliance audit only to raise quota | wait: 3-5 business days for OAuth (audit wait not stated)", "src": "https://developers.google.com/identity/protocols/oauth2/production-readiness/sensitive-scope-verification", "quote": "The sensitive scope verification process typically takes 3-5 business days to complete."}, {"app": "quickbooks", "field": "limits", "text": "Before approval: you only have development keys; the production Show Credentials switch stays hidden.", "src": "https://developer.intuit.com/app/developer/qbo/docs/go-live/publish-app", "quote": "Note: The Show Credentials switch appears only after the App Assessment Questionnaire is approved."}, {"app": "quickbooks", "field": "limits", "text": "Builder tier: 500,000 CorePlus API calls per month, and calls above that are blocked.", "src": "https://developer.intuit.com/app/developer/qbo/docs/get-started/partner-faq", "quote": "the Builder tier will be limited to 500,000 CorePlus API credits per month. Any CorePlus API calls made above the included monthly credit will be blocked entirely."}, {"app": "quickbooks", "field": "requirements", "text": "Production app details need EULA and privacy policy URLs, host domain, launch, disconnect and connect/reconnect URLs.", "src": "https://developer.intuit.com/app/developer/qbo/docs/go-live/publish-app", "quote": "enter the URLs for your End User License Agreement and Privacy Policy. In the next, add your app's host domain, launch URL, disconnect URL, and connect/reconnect URL."}, {"app": "quickbooks", "field": "requirements", "text": "Production redirect URIs must use https, and IP addresses are not allowed.", "src": "https://developer.intuit.com/app/developer/qbo/docs/develop/authentication-and-authorization/set-redirect-uri", "quote": "The Intuit OAuth 2.0 Server can only redirect to URIs beginning with https. IP addresses aren't allowed."}, {"app": "quickbooks", "field": "requirements", "text": "You must get the App Assessment Questionnaire approved to see production credentials.", "src": "https://developer.intuit.com/app/developer/qbo/docs/go-live/publish-app", "quote": "Note: The Show Credentials switch appears only after the App Assessment Questionnaire is approved."}, {"app": "quickbooks", "field": "requirements", "text": "Listed apps must be on the Silver tier or above to avoid delisting.", "src": "https://developer.intuit.com/app/developer/qbo/docs/get-started/partner-faq", "quote": "your app listing will temporarily remain in place, but is subject to removal from the Intuit App Marketplace. To avoid a delisting, you must subscribe to Silver."}, {"app": "quickbooks", "field": "gotchas", "text": "Access tokens last 1 hour; refresh tokens expire after 100 days unused.", "src": "https://developer.intuit.com/app/developer/qbo/docs/develop/authentication-and-authorization/faq", "quote": "Access tokens are valid for 3,600 seconds (or one hour)."}, {"app": "quickbooks", "field": "gotchas", "text": "The refresh token value rotates every 24 hours, so always store the latest one.", "src": "https://developer.intuit.com/app/developer/qbo/docs/develop/authentication-and-authorization/faq", "quote": "We update the value of the refresh_token value every 24 hours hours, or the next time you refresh the access tokens after 24 hours."}, {"app": "quickbooks", "field": "gotchas", "text": "Refresh tokens have a hard limit of 5 years, after which users must reconnect.", "src": "https://developer.intuit.com/app/developer/qbo/docs/develop/authentication-and-authorization/faq", "quote": "Refresh tokens have a hard limit of 5 years. After that, your app must ask users to reauthorize the connection."}, {"app": "quickbooks", "field": "gotchas", "text": "The com.intuit.quickbooks.payment scope can cause Cloudflare Error 1016 if Payments is not enabled.", "src": "https://docs.composio.dev/toolkits/quickbooks", "quote": "If this appears while connecting QuickBooks and the auth config includes the `com.intuit.quickbooks.payment` scope, check whether the QuickBooks Payments module is enabled"}, {"app": "quickbooks", "field": "gotchas", "text": "Sandbox connections need https://sandbox-quickbooks.api.intuit.com as the base URL in Composio.", "src": "https://docs.composio.dev/toolkits/quickbooks", "quote": "For QuickBooks sandbox accounts, pass `https://sandbox-quickbooks.api.intuit.com` as the URL/base URL when initiating the connection."}, {"app": "quickbooks", "field": "gotchas", "text": "The Intuit App Partner Program is available only to partners in the US, UK, Australia and Canada (excluding Quebec).", "src": "https://developer.intuit.com/app/developer/qbo/docs/go-live/publish-app", "quote": "The Intuit App Partner Program is available for partners based in the US, UK, Australia, and Canada (excluding Quebec)."}, {"app": "quickbooks", "field": "review", "text": "Intuit App Assessment Questionnaire, approved before production keys are shown | wait: not stated", "src": "https://developer.intuit.com/app/developer/qbo/docs/go-live/publish-app", "quote": "Note: The Show Credentials switch appears only after the App Assessment Questionnaire is approved."}, {"app": "quickbooks", "field": "cost", "text": "$0 on the Builder tier; Silver is $300 USD/month", "src": "https://developer.intuit.com/app/developer/qbo/docs/get-started/partner-faq", "quote": "The first monthly Program Fee is charged for $300 USD"}, {"app": "twitter", "field": "limits", "text": "Pay-per-use plans are capped at 3 million Post reads per monthly billing cycle.", "src": "https://github.com/xdevplatform/docs/blob/main/x-api/getting-started/pricing.mdx", "quote": "Pay-per-usage plans are capped at **3 million Post reads per monthly billing cycle**."}, {"app": "twitter", "field": "limits", "text": "API requests are blocked when your credit balance or spending limit runs out.", "src": "https://github.com/xdevplatform/docs/blob/main/x-api/getting-started/pricing.mdx", "quote": "When the limit is reached, API requests will be blocked until the next billing cycle."}, {"app": "twitter", "field": "limits", "text": "Posts with a URL cost $0.20 per request.", "src": "https://github.com/xdevplatform/docs/blob/main/x-api/getting-started/pricing.mdx", "quote": "| **Post: Create (with URL)** | &dollar;0.200 per request |"}, {"app": "twitter", "field": "requirements", "text": "You must sign in at console.x.com, accept the Developer Agreement and Policy, and describe your use.", "src": "https://github.com/xdevplatform/docs/blob/main/x-api/getting-started/getting-access.mdx", "quote": "Review and accept the Developer Agreement and Policy."}, {"app": "twitter", "field": "requirements", "text": "Callback URLs must be allowlisted, match exactly, and use https in production.", "src": "https://github.com/xdevplatform/docs/blob/main/fundamentals/developer-apps.mdx", "quote": "- Add callback URLs to your app's allowlist in the Developer Console\n- URLs must match exactly (including trailing slashes)"}, {"app": "twitter", "field": "requirements", "text": "Choose Web App or Automated App to get a client secret (confidential client).", "src": "https://github.com/xdevplatform/docs/blob/main/fundamentals/developer-apps.mdx", "quote": "**Confidential clients** receive a Client Secret. **Public clients** use PKCE only."}, {"app": "twitter", "field": "gotchas", "text": "Credentials are shown once; losing them means regenerating and invalidating the old ones.", "src": "https://github.com/xdevplatform/docs/blob/main/x-api/getting-started/getting-access.mdx", "quote": "Credentials are only displayed once. Store them in a password manager or secure vault. If you lose them, you'll need to regenerate (which invalidates the old ones)."}, {"app": "twitter", "field": "gotchas", "text": "Composio managed credentials for Twitter were removed in February 2026.", "src": "https://docs.composio.dev/toolkits/twitter", "quote": "As of February 2026, Composio managed credentials for the Twitter toolkit have been removed."}, {"app": "twitter", "field": "gotchas", "text": "Post analytics actions return 403 unless you are on an X Enterprise plan.", "src": "https://docs.composio.dev/toolkits/twitter", "quote": "Requires an X Enterprise API plan. Accounts on Free, Basic, Pro, or Pay-Per-Use tiers will receive a 403 Forbidden on every call"}, {"app": "twitter", "field": "gotchas", "text": "Apps can have at most 10 callback URLs.", "src": "https://github.com/xdevplatform/docs/blob/main/fundamentals/developer-apps.mdx", "quote": "Maximum of **10 callback URLs** per app"}, {"app": "twitter", "field": "gotchas", "text": "First-time credit incentives ($20 plus up to $50 match) expire 3 months after they are granted.", "src": "https://github.com/xdevplatform/docs/blob/main/x-api/getting-started/free-credits.mdx", "quote": "Free credits from these incentives **expire 3 months after they are granted**."}, {"app": "twitter", "field": "cost", "text": "Pay-per-use credits, e.g. $0.005 per post read and $0.015 per post created", "src": "https://github.com/xdevplatform/docs/blob/main/x-api/getting-started/pricing.mdx", "quote": "| **Posts: Read** | &dollar;0.005 per resource |"}, {"app": "stripe", "field": "limits", "text": "Connect OAuth with read_write cannot connect to Standard accounts controlled by another platform.", "src": "https://docs.stripe.com/connect/oauth-changes-for-standard-platforms", "quote": "Platforms using OAuth with `read_write` scope can’t connect to Standard accounts that are controlled by another platform."}, {"app": "stripe", "field": "limits", "text": "Stripe Apps before publishing: external testing is capped at 25 testers per app.", "src": "https://docs.stripe.com/stripe-apps/test-app", "quote": "There is a limit of 25 testers per app."}, {"app": "stripe", "field": "requirements", "text": "Each redirect URI must be listed in Connect OAuth settings, and live mode redirect URIs must use HTTPS.", "src": "https://docs.stripe.com/connect/oauth-reference", "quote": "To protect yourself from certain forms of man-in-the-middle attacks, the live mode `redirect_uri` must use a secure HTTPS connection."}, {"app": "stripe", "field": "requirements", "text": "Stripe Apps review needs test credentials, testing guidance and the live-mode public install URL.", "src": "https://docs.stripe.com/stripe-apps/publish-app", "quote": "When submitting your application for review, you must use Live mode Public Install URL."}, {"app": "stripe", "field": "requirements", "text": "Your business cannot be on Stripe's prohibited and restricted businesses list to publish an app.", "src": "https://docs.stripe.com/stripe-apps/publish-app", "quote": "Your business purpose can’t be on the Stripe [Prohibited and Restricted Businesses](https://stripe.com/legal/restricted-businesses) list."}, {"app": "stripe", "field": "gotchas", "text": "Stripe says OAuth is not recommended for new Connect platforms.", "src": "https://docs.stripe.com/connect/oauth-standard-accounts", "quote": "OAuth isn’t recommended for new"}, {"app": "stripe", "field": "gotchas", "text": "New Connect extensions can no longer be built; Stripe Apps replaced them.", "src": "https://docs.stripe.com/building-extensions", "quote": "You can no longer build new Connect extensions."}, {"app": "stripe", "field": "gotchas", "text": "Only extensions can use the read_only scope, so new platforms get read_write.", "src": "https://docs.stripe.com/connect/oauth-changes-for-standard-platforms", "quote": "Only Extensions can use `read_only`, which ensures that platforms can’t read other applications’ data."}, {"app": "stripe", "field": "gotchas", "text": "The Connect token call uses your platform's secret API key as client_secret.", "src": "https://docs.stripe.com/connect/oauth-reference", "quote": "Make this call using your secret API key as a `client_secret` POST parameter:"}, {"app": "stripe", "field": "gotchas", "text": "Each client_id is either live or test, so use the matching one per environment.", "src": "https://docs.stripe.com/connect/oauth-standard-accounts", "quote": "Each `client_id` is either a live or test ID. Use a Sandbox `client_id` to connect to a Sandbox account."}, {"app": "stripe", "field": "gotchas", "text": "Stripe Apps OAuth access tokens expire in 1 hour; refresh tokens last 1 year and roll on use.", "src": "https://docs.stripe.com/stripe-apps/api-authentication/oauth", "quote": "Access tokens expire in 1 hour, and refresh tokens expire after 1 year. Refresh tokens are also rolled on every exchange"}, {"app": "googledrive", "field": "limits", "text": "Before approval: Testing mode is limited to 100 test users listed on the consent screen.", "src": "https://support.google.com/cloud/answer/15549945", "quote": "Projects configured with a publishing status of Testing are limited to up to 100 test users listed in the OAuth consent screen."}, {"app": "googledrive", "field": "limits", "text": "Before approval: test-user authorizations and refresh tokens expire 7 days after consent.", "src": "https://support.google.com/cloud/answer/15549945", "quote": "Authorizations by a test user will expire seven days from the time of consent. If your OAuth client requests an offline access type and receives a refresh token, that token will also expire."}, {"app": "googledrive", "field": "limits", "text": "Before approval: an In-production app requesting unapproved sensitive or restricted scopes shows the unverified app screen.", "src": "https://support.google.com/cloud/answer/15549945", "quote": "Google will display an Unverified apps warning message if your project's OAuth clients request authorization of scopes considered sensitive or restricted before your project has completed verification"}, {"app": "googledrive", "field": "limits", "text": "Before approval: unverified apps are capped at 100 new users for the lifetime of the project, and the cap cannot be reset.", "src": "https://support.google.com/cloud/answer/13463817", "quote": "Please note the user cap applies over the entire lifetime of the project, and it cannot be reset or changed."}, {"app": "googledrive", "field": "requirements", "text": "Verify ownership of your authorized domains in Google Search Console.", "src": "https://developers.google.com/identity/protocols/oauth2/production-readiness/sensitive-scope-verification", "quote": "Verify ownership of your project's authorized domains within the Google Search Console ."}, {"app": "googledrive", "field": "requirements", "text": "Host a public home page and a privacy policy on the same domain, both linked from the consent screen.", "src": "https://developers.google.com/identity/protocols/oauth2/production-readiness/sensitive-scope-verification", "quote": "The privacy policy must be visible to users, hosted within the same domain as your application's home page, and linked to on the OAuth consent screen of the Google API Console."}, {"app": "googledrive", "field": "requirements", "text": "The privacy policy must disclose how the app accesses, uses, stores, or shares Google user data.", "src": "https://developers.google.com/identity/protocols/oauth2/production-readiness/sensitive-scope-verification", "quote": "The privacy policy must disclose the manner in which your application accesses, uses, stores, or shares Google user data."}, {"app": "googledrive", "field": "requirements", "text": "Give a written justification for each sensitive scope, including why a narrower scope is not enough.", "src": "https://developers.google.com/identity/protocols/oauth2/production-readiness/sensitive-scope-verification", "quote": "Prepare a detailed justification for each requested sensitive scope, as well as an explanation for why a narrower scope isn't sufficient."}, {"app": "googledrive", "field": "requirements", "text": "Submit an unlisted YouTube video showing the consent flow, the client ID in the address bar, and each scope in use.", "src": "https://developers.google.com/identity/protocols/oauth2/production-readiness/sensitive-scope-verification", "quote": "Show that the browser address bar of the OAuth consent screen correctly includes your app's OAuth client ID."}, {"app": "googledrive", "field": "requirements", "text": "You must publish your branding before you can request verification for data access.", "src": "https://developers.google.com/identity/protocols/oauth2/production-readiness/sensitive-scope-verification", "quote": "Note that you must have a published branding status before you can request verification for data access."}, {"app": "googledrive", "field": "requirements", "text": "Restricted Drive scopes are allowed only for backup and sync, productivity and education, or reporting and security apps.", "src": "https://developers.google.com/workspace/drive/api/guides/api-specific-auth", "quote": "Only specific application types are permitted to use restricted scopes for Google Drive. To qualify, your app must fall into one of the following categories:"}, {"app": "googledrive", "field": "requirements", "text": "Apps that store or transmit restricted scope data on servers must pass a security assessment.", "src": "https://developers.google.com/workspace/drive/api/guides/api-specific-auth", "quote": "If you store restricted scope data on servers (or transmit), then you must go through a security assessment."}, {"app": "googledrive", "field": "requirements", "text": "The assessment uses the App Defense Alliance CASA framework and must be renewed every 12 months.", "src": "https://support.google.com/cloud/answer/13465431", "quote": "we are leveraging the industry standard App Defense Alliance and its Cloud App Security Assessment framework (CASA)"}, {"app": "googledrive", "field": "requirements", "text": "Internal-only apps (Workspace-owned project, Internal audience) skip verification and the 100-user cap but only work in that org.", "src": "https://support.google.com/cloud/answer/13464323", "quote": "Your app will not be subject to the unverified app screen or the 100-user cap if it's designated as internal-only.  However, only users in the Workspace or Cloud Identity organization will be able"}, {"app": "googledrive", "field": "gotchas", "text": "drive, drive.readonly, drive.metadata, drive.metadata.readonly, drive.activity and drive.scripts are restricted.", "src": "https://developers.google.com/workspace/drive/api/guides/api-specific-auth", "quote": "https://www.googleapis.com/auth/drive View and manage all your Drive files. https://www.googleapis.com/auth/drive.readonly"}, {"app": "googledrive", "field": "gotchas", "text": "drive.file, drive.appdata and drive.install are non-sensitive; drive.apps.readonly is sensitive.", "src": "https://developers.google.com/workspace/drive/api/guides/api-specific-auth", "quote": "Sensitive scopes Scope code Description https://www.googleapis.com/auth/drive.apps.readonly View apps authorized to access your Drive."}, {"app": "googledrive", "field": "gotchas", "text": "drive.file only covers files your app creates or the user opens or picks with your app, not the whole Drive.", "src": "https://developers.google.com/workspace/drive/api/guides/api-specific-auth", "quote": "Create new Drive files, or modify existing files, that you open with an app or that the user shares with an app while using the Google Picker API or the app's file picker."}, {"app": "googledrive", "field": "gotchas", "text": "Google's Trust and Safety team tells you when to start the CASA assessment; it is the last step of the review.", "src": "https://support.google.com/cloud/answer/13465431", "quote": "the Google Trust and Safety team will contact you when it is time to initiate the security assessment process."}, {"app": "googledrive", "field": "gotchas", "text": "Adding a new restricted scope later may require a new assessment covering it.", "src": "https://developers.google.com/identity/protocols/oauth2/production-readiness/restricted-scope-verification", "quote": "If your app adds a new restricted scope, your app might need to be reassessed to cover the additional scope if it wasn't included in a prior security assessment."}, {"app": "googledrive", "field": "gotchas", "text": "Google's FAQ estimates sensitive scope verification at 10 business days, which is longer than the 3-5 days on the developer page.", "src": "https://support.google.com/cloud/answer/13463817", "quote": "10 Business days"}, {"app": "googledrive", "field": "gotchas", "text": "Limits apply to refresh tokens: 100 per Google Account per client ID, and creating a new one silently invalidates the oldest.", "src": "https://developers.google.com/identity/protocols/oauth2", "quote": "If the limit is reached, creating a new refresh token automatically invalidates the oldest refresh token without warning."}, {"app": "googledrive", "field": "gotchas", "text": "Refresh tokens stop working after 6 months unused or if the user revokes access.", "src": "https://developers.google.com/identity/protocols/oauth2", "quote": "The refresh token has not been used for six months."}, {"app": "googledrive", "field": "gotchas", "text": "Your OAuth redirect URI must exactly match oauth_redirect_uri in the Composio auth config; some defaults still use /api/v1/auth-apps/add.", "src": "https://docs.composio.dev/docs/auth-configuration/custom-auth-configs", "quote": "The redirect URI in your OAuth app must exactly match oauth_redirect_uri in your Composio auth config. Some toolkit defaults still use https://backend.composio.dev/api/v1/auth-apps/add"}, {"app": "googledrive", "field": "gotchas", "text": "Use separate Google Cloud projects for testing and production, and submit only the production project for verification.", "src": "https://support.google.com/cloud/answer/13464323", "quote": "Please create separate projects for development/testing/staging and production as per the Google OAuth policy ."}, {"app": "googledrive", "field": "gotchas", "text": "Workspace admins can restrict sensitive scopes to OAuth clients they explicitly mark as trusted.", "src": "https://developers.google.com/identity/protocols/oauth2/production-readiness/sensitive-scope-verification", "quote": "Google Workspace organization administrators might restrict access to sensitive scopes to prevent access by OAuth client IDs that the organization doesn't explicitly mark as trusted."}, {"app": "googledrive", "field": "cost", "text": "Google charges no fee; the CASA assessor's fee is agreed directly with them", "src": "https://support.google.com/cloud/answer/13463817", "quote": "The cost for such a service is agreed on between the developer and the assessor without any involvement from Google."}, {"app": "github", "field": "limits", "text": "OAuth tokens use the user's rate limit of 5,000 requests per hour.", "src": "https://docs.github.com/en/apps/oauth-apps/building-oauth-apps/differences-between-github-apps-and-oauth-apps", "quote": "OAuth tokens use the user's rate limit of 5,000 requests per hour."}, {"app": "github", "field": "limits", "text": "A private GitHub App can only be installed on the account that owns it.", "src": "https://docs.github.com/en/apps/creating-github-apps/registering-a-github-app/making-a-github-app-public-or-private", "quote": "If you set your GitHub App registration to private, it can only be installed on the account that owns the app."}, {"app": "github", "field": "requirements", "text": "Register the app with a name, homepage URL and authorization callback URL.", "src": "https://docs.github.com/en/apps/oauth-apps/building-oauth-apps/creating-an-oauth-app", "quote": "In \"Authorization callback URL\", type the callback URL of your app."}, {"app": "github", "field": "requirements", "text": "Use only information you consider public in the app's fields, since users see them.", "src": "https://docs.github.com/en/apps/oauth-apps/building-oauth-apps/creating-an-oauth-app", "quote": "Only use information in your OAuth app that you consider public. Avoid using sensitive data, such as internal URLs, when creating an OAuth app."}, {"app": "github", "field": "requirements", "text": "A user or organization can own up to 100 OAuth apps.", "src": "https://docs.github.com/en/apps/oauth-apps/building-oauth-apps/creating-an-oauth-app", "quote": "A user or organization can own up to 100 OAuth apps."}, {"app": "github", "field": "requirements", "text": "A GitHub App must be set to 'Any account' (public) before other accounts can install it.", "src": "https://docs.github.com/en/apps/creating-github-apps/registering-a-github-app/registering-a-github-app", "quote": "Under \"Where can this GitHub App be installed?\", select Only on this account or Any account ."}, {"app": "github", "field": "gotchas", "text": "'Expire user access tokens' is on by default for new OAuth apps; uncheck it only if your code can't refresh.", "src": "https://docs.github.com/en/apps/oauth-apps/building-oauth-apps/creating-an-oauth-app", "quote": "Expire user access tokens is enabled by default. If your app's authentication code hasn't been updated to support short-lived tokens, uncheck the box until support is added."}, {"app": "github", "field": "gotchas", "text": "Expiring tokens last 8 hours and the refresh token 6 months; each refresh invalidates the old pair.", "src": "https://docs.github.com/en/apps/oauth-apps/building-oauth-apps/authorizing-oauth-apps", "quote": "The access token expires after eight hours, and the refresh token expires after six months without use."}, {"app": "github", "field": "gotchas", "text": "Non-expiring OAuth tokens are revoked automatically if unused for one year.", "src": "https://docs.github.com/en/authentication/keeping-your-account-and-data-secure/token-expiration-and-revocation", "quote": "GitHub will automatically revoke an OAuth token or personal access token when the token hasn't been used in one year."}, {"app": "github", "field": "gotchas", "text": "Only 10 tokens per user/app/scope are kept; creating an 11th revokes an older one.", "src": "https://docs.github.com/en/authentication/keeping-your-account-and-data-secure/token-expiration-and-revocation", "quote": "If an application creates more than ten tokens for the same user and the same scopes, GitHub revokes one of the existing tokens with the same user/application/scope combination"}, {"app": "github", "field": "gotchas", "text": "New organizations enable OAuth app access restrictions by default, so an org owner must approve your OAuth app.", "src": "https://docs.github.com/en/organizations/managing-oauth-access-to-your-organizations-data/about-oauth-app-access-restrictions", "quote": "When you create a new organization, OAuth app access restrictions are enabled by default. Organization owners can disable OAuth app access restrictions at any time."}, {"app": "github", "field": "gotchas", "text": "With a GitHub App, users must install it on their account or org separately; Composio doesn't supply the install link.", "src": "https://docs.composio.dev/toolkits/github", "quote": "Composio does not currently provide the GitHub App installation link automatically during this flow. Provide your GitHub App installation link to the user"}, {"app": "github", "field": "gotchas", "text": "OAuth apps act only as a user; GitHub Apps can also act as the app and get finer-grained permissions.", "src": "https://docs.github.com/en/apps/oauth-apps/building-oauth-apps/creating-an-oauth-app", "quote": "OAuth apps can only act on behalf of a user while GitHub Apps can either act on behalf of a user or independently of a user. GitHub Apps use fine-grained permissions"}, {"app": "dropbox", "field": "limits", "text": "Before approval: a development app links only your own account until you click Enable additional users.", "src": "https://www.dropbox.com/developers/reference/developer-guide", "quote": "When you first create a Dropbox API app, it’s given development status and can only be connected to your own account."}, {"app": "dropbox", "field": "limits", "text": "Before approval: a development app can link at most 500 Dropbox users.", "src": "https://www.dropbox.com/developers/reference/developer-guide", "quote": "it can only be linked with up to 500 total Dropbox users ."}, {"app": "dropbox", "field": "limits", "text": "After 50 linked users you have two weeks to get production approval, or new links are frozen.", "src": "https://www.dropbox.com/developers/reference/developer-guide", "quote": "once your app links 50 Dropbox users, you will have two weeks to apply for and receive production status approval before your app’s ability to link additional Dropbox users will be frozen"}, {"app": "dropbox", "field": "requirements", "text": "The app must follow Dropbox's branding guidelines and terms, or production is rejected.", "src": "https://www.dropbox.com/developers/reference/developer-guide", "quote": "Before applying for production, make sure your app adheres to the developer branding guidelines and terms and conditions . It will be rejected if it doesn’t."}, {"app": "dropbox", "field": "requirements", "text": "Request the least privileged permissions; Dropbox reviews scope breadth at production.", "src": "https://www.dropbox.com/developers/reference/developer-guide", "quote": "Your app should use the least privileged permission it can. When applying for production, we’ll review that your app doesn’t request an unnecessarily broad permission"}, {"app": "dropbox", "field": "requirements", "text": "The production application asks how the app uses the API and for an app icon.", "src": "https://www.dropbox.com/developers/reference/developer-guide", "quote": "you’ll be prompted to supply additional information such as how your app uses the API, and to upload an icon for the app."}, {"app": "dropbox", "field": "requirements", "text": "The app name cannot include Dropbox, start with drop, or use DBX or DB.", "src": "https://www.dropbox.com/developers/reference/branding-guide", "quote": "It can’t begin with “drop”, be similar to Dropbox in sound or spelling, or otherwise refer to Dropbox (for example, don’t use “DBX” or “DB” or “DfB”)."}, {"app": "dropbox", "field": "gotchas", "text": "Production review does not start until 50 linked users unless you request early review.", "src": "https://www.dropbox.com/developers/reference/developer-guide", "quote": "it will not be reviewed until your app has linked with at least 50 Dropbox users"}, {"app": "dropbox", "field": "gotchas", "text": "A frozen app can only be unfrozen by getting production approval, not by unlinking users.", "src": "https://www.dropbox.com/developers/reference/developer-guide", "quote": "for apps that have been temporarily frozen, the only way to unfreeze your app is to apply for and receive production status . Simply unlinking all of your users will not unfreeze your app."}, {"app": "dropbox", "field": "gotchas", "text": "You cannot change the app name after production approval.", "src": "https://www.dropbox.com/developers/reference/developer-guide", "quote": "Keep in mind that once your app has production status, you can’t change its name."}, {"app": "dropbox", "field": "gotchas", "text": "Access tokens are short-lived; add token_access_type=offline to get a refresh token.", "src": "https://www.dropbox.com/developers/reference/oauth-guide", "quote": "you’ll need to include token_access_type=offline as a parameter on your Authorization URL in order to return a refresh_token"}, {"app": "dropbox", "field": "gotchas", "text": "Redirect URIs must exactly match a registered value in the App Console.", "src": "https://www.dropbox.com/developers/reference/oauth-guide", "quote": "You’ll need to register the exact redirect URI(s) your app may use in the App Console for your application."}, {"app": "dropbox", "field": "review", "text": "Dropbox production status approval | wait: not stated; review starts after 50 linked users", "src": "https://www.dropbox.com/developers/reference/developer-guide", "quote": "it will not be reviewed until your app has linked with at least 50 Dropbox users"}, {"app": "notion", "field": "requirements", "text": "Set the integration type to Public to use OAuth; internal integrations only use an API token.", "src": "https://composio.dev/auth/notion", "quote": "Important: API Key authentication only works with Internal integrations . Public integrations must use OAuth ."}, {"app": "notion", "field": "requirements", "text": "Redirect URIs must use HTTPS, match exactly, and have no trailing slash, fragment or wildcard.", "src": "https://composio.dev/auth/notion", "quote": "Must use HTTPS Must match the URI exactly No trailing slash No URL fragments, wildcards, or relative paths"}, {"app": "notion", "field": "requirements", "text": "Users pick which pages to share during authorization, then press Allow access.", "src": "https://www.notion.com/help/add-and-manage-connections-with-the-api", "quote": "Choose the pages you would like the connection to be able to access, and then press Allow access ."}, {"app": "notion", "field": "gotchas", "text": "Notion has no OAuth scopes; access comes from the pages and databases users share.", "src": "https://docs.composio.dev/toolkits/notion", "quote": "No. Notion controls access by granting integrations access to specific pages and databases, not through scopes."}, {"app": "notion", "field": "gotchas", "text": "Actions show the integration's name and logo, not the user's; your own app lets you set them.", "src": "https://docs.composio.dev/toolkits/notion", "quote": "The name and logo shown come from the integration configuration. To use a custom name or logo, create your own Notion integration."}, {"app": "notion", "field": "gotchas", "text": "Connecting the same user again issues a new token pair and can invalidate the older refresh token.", "src": "https://docs.composio.dev/toolkits/notion", "quote": "If the same user connects to the same Notion app again, whether it is Composio-managed or custom, Notion can issue a new token pair and invalidate the older refresh_token ."}, {"app": "notion", "field": "gotchas", "text": "Keep one connection per real user per Notion app to avoid broken refresh tokens.", "src": "https://docs.composio.dev/toolkits/notion", "quote": "To avoid this, keep one active Notion connection per real user for a given Notion app"}, {"app": "notion", "field": "gotchas", "text": "A user removing the connection in Settings > Connections revokes the tokens.", "src": "https://docs.composio.dev/toolkits/notion", "quote": "If a user removes the Composio-managed or custom Notion app there, the existing token set should be treated as revoked"}, {"app": "notion", "field": "gotchas", "text": "On Enterprise, workspace owners can restrict which connections members may install.", "src": "https://www.notion.com/help/add-and-manage-connections-with-the-api", "quote": "Note: On Enterprise plans, workspace owners can restrict which connections members are allowed to install."}, {"app": "notion", "field": "gotchas", "text": "With your own app, Notion webhooks need you to paste back a verification token Notion sends to Composio.", "src": "https://docs.composio.dev/toolkits/notion", "quote": "Notion sends a verification token to the ingress endpoint, and you paste that token back into Notion to finalize."}, {"app": "microsoftteams", "field": "limits", "text": "Before verification: the consent prompt shows 'Unverified' instead of a publisher name.", "src": "https://learn.microsoft.com/en-us/entra/identity-platform/application-consent-experience", "quote": "If the app isn't publisher verified, \"Unverified\" is displayed instead of a publisher name."}, {"app": "microsoftteams", "field": "limits", "text": "Before verification: with risk-based step-up consent on, users in other tenants can't consent to multitenant apps registered after 8 Nov 2020 that ask for more than sign-in and profile.", "src": "https://learn.microsoft.com/en-us/entra/identity-platform/publisher-verification-overview", "quote": "The policy applies to apps that were registered after November 8, 2020, which use OAuth 2.0 to request permissions that extend beyond the basic sign-in and read user profile"}, {"app": "microsoftteams", "field": "requirements", "text": "Register the app in Microsoft Entra ID as at least an Application Developer.", "src": "https://learn.microsoft.com/en-us/entra/identity-platform/quickstart-register-app", "quote": "Sign in to the Microsoft Entra admin center as at least an Application Developer."}, {"app": "microsoftteams", "field": "requirements", "text": "For other organizations, set supported account types to multiple Entra ID tenants, with or without personal Microsoft accounts.", "src": "https://learn.microsoft.com/en-us/entra/identity-platform/quickstart-register-app", "quote": "Multiple Entra ID tenants For multitenant apps when you want users in any Microsoft Entra tenant to be able to use your application."}, {"app": "microsoftteams", "field": "requirements", "text": "Publisher verification needs a verified Microsoft AI Cloud Partner Program (formerly MPN) partner global account ID.", "src": "https://learn.microsoft.com/en-us/entra/identity-platform/publisher-verification-overview", "quote": "The developer must have a Partner One ID for a valid Microsoft AI Cloud Partner Program account that has completed the verification process. The CPP account must be the partner global account (PGA)"}, {"app": "microsoftteams", "field": "requirements", "text": "The app must be registered with a work or school account, not a personal Microsoft account, to be publisher verified.", "src": "https://learn.microsoft.com/en-us/entra/identity-platform/publisher-verification-overview", "quote": "Apps that are registered by using a Microsoft account can't be publisher verified."}, {"app": "microsoftteams", "field": "requirements", "text": "The publisher domain can't be *.onmicrosoft.com and must match the Partner Center email domain or a DNS-verified custom domain.", "src": "https://learn.microsoft.com/en-us/entra/identity-platform/publisher-verification-overview", "quote": "(NOTE__: the app's publisher domain can't be *.onmicrosoft.com to be publisher verified)"}, {"app": "microsoftteams", "field": "requirements", "text": "The person verifying needs Application Administrator or Cloud Application Administrator in Entra, and Microsoft AI Cloud Partner Program Admin or Accounts Admin in Partner Center, and must sign in with MFA.", "src": "https://learn.microsoft.com/en-us/entra/identity-platform/mark-app-as-publisher-verified", "quote": "The user in Partner Center must have the following roles: Microsoft AI Cloud Partner Program Admin or Accounts Admin."}, {"app": "microsoftteams", "field": "gotchas", "text": "Delegated ChannelMessage.Read.All and TeamMember.Read.All require admin consent.", "src": "https://learn.microsoft.com/en-us/graph/permissions-reference", "quote": "Allows an app to read a channel's messages in Microsoft Teams, on behalf of the signed-in user."}, {"app": "microsoftteams", "field": "gotchas", "text": "Delegated Chat.Read, Chat.ReadWrite, ChatMessage.Send, ChannelMessage.Send and Team.ReadBasic.All don't need admin consent.", "src": "https://learn.microsoft.com/en-us/graph/permissions-reference", "quote": "Allows an app to send channel messages in Microsoft Teams, on behalf of the signed-in user."}, {"app": "microsoftteams", "field": "gotchas", "text": "For apps that need admin consent, add an admin sign-up link that sends prompt=consent so one admin approves for the whole tenant.", "src": "https://learn.microsoft.com/en-us/entra/identity-platform/howto-convert-app-to-be-multi-tenant", "quote": "If your application uses permissions that require admin consent, consider adding a button or link where the admin can initiate the action."}, {"app": "microsoftteams", "field": "gotchas", "text": "Application (app-only) permissions always need tenant admin consent.", "src": "https://learn.microsoft.com/en-us/entra/identity-platform/howto-convert-app-to-be-multi-tenant", "quote": "App-only permissions always require a tenant administrator’s consent."}, {"app": "microsoftteams", "field": "gotchas", "text": "Tenant admins can turn off user consent, which makes admin consent mandatory for every app in that tenant.", "src": "https://learn.microsoft.com/en-us/entra/identity-platform/howto-convert-app-to-be-multi-tenant", "quote": "If this capability is disabled, admin consent is always required for the application to be used in the tenant."}, {"app": "microsoftteams", "field": "gotchas", "text": "Microsoft recommends tenants allow user consent only for apps from verified publishers.", "src": "https://learn.microsoft.com/en-us/entra/identity/enterprise-apps/configure-user-consent", "quote": "we recommend that you allow user consent only for applications that have been published by a verified publisher."}, {"app": "microsoftteams", "field": "gotchas", "text": "If an admin consents without prompt=consent, the consent only covers the admin's own account.", "src": "https://learn.microsoft.com/en-us/entra/identity-platform/howto-convert-app-to-be-multi-tenant", "quote": "when the admin successfully consents to the application it applies only for their user account."}, {"app": "microsoftteams", "field": "gotchas", "text": "Client secrets last 24 months at most, and Microsoft recommends under 12 months.", "src": "https://learn.microsoft.com/en-us/entra/identity-platform/how-to-add-credentials", "quote": "Client secret lifetime is limited to two years (24 months) or less."}, {"app": "microsoftteams", "field": "gotchas", "text": "Refresh tokens last 90 days by default, or 24 hours for single-page app redirect URIs.", "src": "https://learn.microsoft.com/en-us/entra/identity-platform/refresh-tokens", "quote": "24 hours for single-page applications. 24 hours for apps that use email one-time passcode authentication flow. 90 days for all other scenarios."}, {"app": "microsoftteams", "field": "cost", "text": "$0: Microsoft doesn't charge for publisher verification and no license is needed", "src": "https://learn.microsoft.com/en-us/entra/identity-platform/publisher-verification-overview", "quote": "Microsoft doesn't charge developers for publisher verification. No license is required to become a verified publisher."}, {"app": "zendesk", "field": "limits", "text": "Before approval: a local OAuth client's tokens only access the single Zendesk instance that created it.", "src": "https://developer.zendesk.com/api-reference/introduction/security-and-auth/", "quote": "An OAuth token gives access to a single Zendesk instance (the one with the OAuth client used to create the token)."}, {"app": "zendesk", "field": "limits", "text": "Third-party apps may not use a customer's API token or the customer's own OAuth client, listed or not.", "src": "https://support.zendesk.com/hc/en-us/articles/9590471542170-Developer-update-Enhanced-security-guidelines-for-third-party-apps-integrations-and-bots", "quote": "(whether it’s listed on the Zendesk Marketplace or not) to use a customer’s API credentials (API token or a customer’s own OAuth client) to authenticate API calls."}, {"app": "zendesk", "field": "requirements", "text": "Apps distributed to multiple Zendesk customers must use global OAuth tokens.", "src": "https://developer.zendesk.com/documentation/marketplace/building-a-marketplace-app/set-up-a-global-oauth-client/", "quote": "If you distribute a public app or an integration app to multiple Zendesk customers, you must use global OAuth tokens to authenticate requests."}, {"app": "zendesk", "field": "requirements", "text": "Requests must come from a d3v- sponsored account; non-d3v- submissions aren't accepted.", "src": "https://developer.zendesk.com/documentation/marketplace/building-a-marketplace-app/set-up-a-global-oauth-client/", "quote": "Ensure the subdomain includes the prefix d3v-. Submissions from non-d3v- accounts aren't accepted."}, {"app": "zendesk", "field": "requirements", "text": "Sponsored d3v- accounts are reserved for developers building Zendesk Marketplace apps.", "src": "https://developer.zendesk.com/documentation/api-basics/getting-started/getting-a-trial-or-sponsored-account-for-development/", "quote": "A sponsored test account is reserved for developers creating applications for the Zendesk Marketplace."}, {"app": "zendesk", "field": "requirements", "text": "The local client's unique identifier must start with zdg- and every field must be filled in.", "src": "https://developer.zendesk.com/documentation/marketplace/building-a-marketplace-app/set-up-a-global-oauth-client/", "quote": "Make sure all fields are completed for the local client. Even if a field is labeled optional, it is required for global clients."}, {"app": "zendesk", "field": "requirements", "text": "Unlisted integrations must still create a Marketplace profile, register the organization and submit for review.", "src": "https://support.zendesk.com/hc/en-us/articles/9590471542170-Developer-update-Enhanced-security-guidelines-for-third-party-apps-integrations-and-bots", "quote": "If you haven’t listed your integration on the Zendesk Marketplace, you need to create your Zendesk Marketplace profile, register your organization and submit your app for review and approval."}, {"app": "zendesk", "field": "requirements", "text": "Global OAuth clients must support the refresh token flow from January 31, 2026.", "src": "https://support.zendesk.com/hc/en-us/articles/9590471542170-Developer-update-Enhanced-security-guidelines-for-third-party-apps-integrations-and-bots", "quote": "Supporting the refresh token flow will be required for all global OAuth clients starting January 31, 2026."}, {"app": "zendesk", "field": "gotchas", "text": "Save the client secret and identifier first; you lose the client admin page after conversion to global.", "src": "https://developer.zendesk.com/documentation/marketplace/building-a-marketplace-app/set-up-a-global-oauth-client/", "quote": "Make sure you note down the secret and the identifier before making your request. You will lose access to the client administration page after the local client is converted to a global client."}, {"app": "zendesk", "field": "gotchas", "text": "Zendesk may cap allowed scopes; requesting others returns 400 invalid_scope.", "src": "https://developer.zendesk.com/documentation/marketplace/building-a-marketplace-app/set-up-a-global-oauth-client/", "quote": "If your app requests a scope that is not included in the client's allowed scopes, the authorization request fails with a 400 Bad Request response and an invalid_scope error"}, {"app": "zendesk", "field": "gotchas", "text": "Scope changes after approval go through Zendesk Support, since only Marketplace Operations can edit global clients.", "src": "https://developer.zendesk.com/documentation/marketplace/building-a-marketplace-app/set-up-a-global-oauth-client/", "quote": "Because global clients can only be edited by the Zendesk Marketplace operations team, you'll need to contact Zendesk Support to request a change to your client's allowed scopes."}, {"app": "zendesk", "field": "gotchas", "text": "New global clients get 30-minute access tokens and 30-day refresh tokens by default.", "src": "https://support.zendesk.com/hc/en-us/articles/10212201463962-Announcing-the-required-expiration-of-global-OAuth-access-and-refresh-tokens", "quote": "we are enforcing the default TTL (time to live) for access and refresh tokens for (1) all newly created global OAuth clients"}, {"app": "zendesk", "field": "gotchas", "text": "A sponsored account is suspended if used to provide real customer support.", "src": "https://developer.zendesk.com/documentation/api-basics/getting-started/getting-a-trial-or-sponsored-account-for-development/", "quote": "Note: Zendesk will suspend any sponsored Support account used to provide actual support."}, {"app": "zendesk", "field": "gotchas", "text": "Integration apps must send custom headers identifying the integration, organization ID and Marketplace app ID.", "src": "https://support.zendesk.com/hc/en-us/articles/9590471542170-Developer-update-Enhanced-security-guidelines-for-third-party-apps-integrations-and-bots", "quote": "each API call must include custom headers that specify the name of the integration, the organization ID, and the Marketplace app ID."}, {"app": "zendesk", "field": "review", "text": "Global OAuth client request through the Zendesk Marketplace portal | wait: not stated", "src": "https://developer.zendesk.com/documentation/marketplace/building-a-marketplace-app/set-up-a-global-oauth-client/", "quote": "Sign in to the Zendesk Marketplace portal. Select Global OAuth from the menu on the left side, and then click the Request new OAuth button."}, {"app": "zendesk", "field": "cost", "text": "No fee is mentioned for the global OAuth request", "src": "https://developer.zendesk.com/documentation/marketplace/building-a-marketplace-app/set-up-a-global-oauth-client/", "quote": ""}, {"app": "monday", "field": "limits", "text": "Private apps can only be used inside the account that built them.", "src": "https://developer.monday.com/apps/docs/install-and-share-your-apps", "quote": "Private apps are those developed for use inside the same monday account. Users outside of the account can't access or use the app"}, {"app": "monday", "field": "limits", "text": "Shared apps without monday approval show a banner saying monday hasn't vetted them.", "src": "https://developer.monday.com/apps/docs/install-and-share-your-apps", "quote": "applications without monday approval will show a banner to indicate that the monday.com team hasn't vetted them"}, {"app": "monday", "field": "limits", "text": "You can restrict a shared app to specific monday accounts.", "src": "https://developer.monday.com/apps/docs/install-and-share-your-apps", "quote": "You can select Share with specific monday accounts and list their account URLs if you want to restrict access to specific accounts."}, {"app": "monday", "field": "requirements", "text": "Create the app in the Developer Center; viewers cannot access it.", "src": "https://developer.monday.com/apps/docs/the-developer-center", "quote": "Viewers can't access the Developer Center"}, {"app": "monday", "field": "requirements", "text": "Accept the developer terms on the Share tab to get a shareable install link.", "src": "https://developer.monday.com/apps/docs/install-and-share-your-apps", "quote": "Accept the developer terms and click Share App."}, {"app": "monday", "field": "requirements", "text": "Requested scopes must match the scopes configured on the app.", "src": "https://developer.monday.com/apps/docs/oauth", "quote": "All requested scopes must match the list you configured in your app."}, {"app": "monday", "field": "requirements", "text": "Redirect URI must match one of the redirect URLs added to the app.", "src": "https://developer.monday.com/apps/docs/oauth", "quote": "URL to redirect back on approval/denial. Must match one of the redirect URLs added to your app."}, {"app": "monday", "field": "gotchas", "text": "If the app is not installed in the workspace, users see 'App is not installed'.", "src": "https://docs.composio.dev/toolkits/monday", "quote": "If the app is not installed, Monday can stop the connection flow with an \"App is not installed\" message."}, {"app": "monday", "field": "gotchas", "text": "A workspace admin installs the app once; then users can connect.", "src": "https://docs.composio.dev/toolkits/monday", "quote": "A Monday workspace admin only needs to install the app once per workspace. After the admin approves the installation, users in that workspace can connect their Monday accounts normally."}, {"app": "monday", "field": "gotchas", "text": "Legacy OAuth tokens do not expire and there are no refresh tokens.", "src": "https://developer.monday.com/apps/docs/oauth", "quote": "Tokens do not expire and are valid until the user uninstalls your app. Our OAuth flow does not support refresh tokens."}, {"app": "monday", "field": "gotchas", "text": "A newer OAuth 2.1 flow adds expiring access tokens and refresh tokens.", "src": "https://developer.monday.com/apps/docs/oauth", "quote": "monday.com now supports an improved OAuth 2.1 flow with expiring access tokens, refresh tokens, and token revocation."}, {"app": "monday", "field": "gotchas", "text": "The authorization code is valid for only 10 minutes.", "src": "https://developer.monday.com/apps/docs/oauth", "quote": "The authorization code is only valid for 10 minutes"}, {"app": "monday", "field": "gotchas", "text": "New apps built mainly with no-code tools or AI 'vibe code' are not eligible for the marketplace.", "src": "https://developer.monday.com/apps/docs/submit-your-app", "quote": "New apps built primarily using no-code platforms or AI-generated “vibe code” are not eligible for marketplace approval."}, {"app": "calendly", "field": "limits", "text": "Rate limit is per user: 50 requests/min on Free plans, 500/min on paid plans.", "src": "https://developer.calendly.com/api-docs/overview/rate-limits", "quote": "Rate limits are enforced per user."}, {"app": "calendly", "field": "limits", "text": "Only 8 OAuth tokens per user can be requested within one minute.", "src": "https://developer.calendly.com/api-docs/overview/rate-limits", "quote": "Only 8 OAuth tokens per user can be requested within a span of 1 minute."}, {"app": "calendly", "field": "limits", "text": "Webhook subscriptions need the user on a paid Standard, Teams or Enterprise plan.", "src": "https://developer.calendly.com/docs/getting-started/frequently-asked-questions", "quote": "the Calendly user account for which the webhook subscription is being made will need a paid subscription on the Standard, Teams, or Enterprise plan."}, {"app": "calendly", "field": "requirements", "text": "Sign up for a developer account with GitHub or Google; it is separate from your Calendly user account.", "src": "https://developer.calendly.com/creating-an-oauth-app", "quote": "Note: This is not your Calendly user account and is not associated with your Calendly user account."}, {"app": "calendly", "field": "requirements", "text": "Production apps must use an HTTPS redirect URI; Sandbox allows http localhost.", "src": "https://developer.calendly.com/creating-an-oauth-app", "quote": "For the Sandbox environment, we allow HTTP with localhost domain. Example: http://localhost:1234"}, {"app": "calendly", "field": "requirements", "text": "Calendly recommends a Sandbox app for development and a second app for Production.", "src": "https://developer.calendly.com/creating-an-oauth-app", "quote": "We recommend starting with Sandbox for development and creating a second application for Production when ready to go live with customer data."}, {"app": "calendly", "field": "gotchas", "text": "The client secret and webhook signing key are shown only once at creation.", "src": "https://developer.calendly.com/creating-an-oauth-app", "quote": "these values are only displayed when the OAuth application is created"}, {"app": "calendly", "field": "gotchas", "text": "Access tokens expire after 2 hours.", "src": "https://developer.calendly.com/api-docs/calendly-o-auth/o-auth/post-oauth-refresh-token", "quote": "Access Tokens expire after 2 hours."}, {"app": "calendly", "field": "gotchas", "text": "Refresh tokens are single-use and rotate on every refresh.", "src": "https://developer.calendly.com/docs/authentication/refresh-token-rotation-guide", "quote": "each refresh token can only be used once — when you use it to refresh, that refresh token becomes invalid and you’ll get a new refresh token in the response."}, {"app": "calendly", "field": "gotchas", "text": "Tokens are revoked if the user changes login email, password or login method.", "src": "https://developer.calendly.com/docs/getting-started/frequently-asked-questions", "quote": "Both OAuth and personal access tokens will be revoked if:"}, {"app": "calendly", "field": "gotchas", "text": "Users cannot approve individual scopes; the app's configured scopes are requested.", "src": "https://docs.composio.dev/toolkits/calendly", "quote": "Calendly does not let end users selectively approve individual scopes during the OAuth connection flow. The scopes configured in your Calendly OAuth app are the scopes that will be requested"}, {"app": "calendly", "field": "gotchas", "text": "A few endpoints require the Enterprise plan.", "src": "https://developer.calendly.com/docs/getting-started/frequently-asked-questions", "quote": "with the exception of a few endpoints that are specific to our Enterprise plan"}, {"app": "box", "field": "limits", "text": "If an enterprise turns on Disable unpublished apps by default, its admin must enable your OAuth 2.0 app first.", "src": "https://github.com/box/developer.box.com/blob/main/content/guides/authorization/index.md", "quote": "Enable in **Integrations** > **Platform Apps Manager** > **User Authentication Apps** > Select Platform App > Use **More** menu to enable the app."}, {"app": "box", "field": "requirements", "text": "Redirect URIs must be HTTPS, or HTTP only for localhost or loopback addresses.", "src": "https://github.com/box/developer.box.com/blob/main/content/guides/authentication/oauth2/oauth2-setup.md", "quote": "These must be valid URIs that are HTTPS, or a less secure HTTP for localhost or loopback address."}, {"app": "box", "field": "requirements", "text": "Box Integrations listing accepts only OAuth 2.0 apps that are finished and production-ready.", "src": "https://github.com/box/developer.box.com/blob/main/content/guides/applications/integrations/index.md", "quote": "The platform app leverages OAuth 2.0 authentication, as Integrations do not support any other authentication methods."}, {"app": "box", "field": "gotchas", "text": "You cannot change the authentication method after creating the app.", "src": "https://github.com/box/developer.box.com/blob/main/content/guides/authentication/oauth2/oauth2-setup.md", "quote": "Once you make a selection, you will not be able to change to a different authentication method without creating a new application."}, {"app": "box", "field": "gotchas", "text": "Refresh tokens are single-use and expire after 60 days, after which users must re-authorize.", "src": "https://github.com/box/developer.box.com/blob/main/content/guides/authentication/tokens/refresh.md", "quote": "A Refresh Token is valid for 60 days and can be used to obtain a new Access Token and Refresh Token only once."}, {"app": "box", "field": "gotchas", "text": "Admins enable an OAuth 2.0 app by entering its client ID under Platform > Platform Apps.", "src": "https://support.box.com/hc/en-us/articles/360044196653-Managing-custom-apps", "quote": "In the top-right corner of the window, click Add + then enter the user authentication application client ID."}, {"app": "box", "field": "gotchas", "text": "Redirect URIs are checked by exact match.", "src": "https://github.com/box/developer.box.com/blob/main/content/guides/authentication/oauth2/oauth2-setup.md", "quote": "This will be an exact match check, meaning the URIs must be exactly the same."}, {"app": "jira", "field": "limits", "text": "Before sharing: a new 3LO app is private, so only you can install and use it.", "src": "https://developer.atlassian.com/cloud/jira/platform/oauth-2-3lo-apps/", "quote": "When you create an OAuth 2.0 (3LO) app, it's private by default. This means that only you can install and use it."}, {"app": "jira", "field": "limits", "text": "Before approval: users installing an unapproved integration are warned it hasn't been reviewed by Atlassian.", "src": "https://developer.atlassian.com/cloud/jira/platform/oauth-2-3lo-apps/", "quote": "Users trying to install an unapproved OAuth 2.0 integration are warned that the app has not yet been reviewed by Atlassian."}, {"app": "jira", "field": "limits", "text": "Sharing doesn't list the app on the Marketplace; you must send the authorization URL to every user.", "src": "https://developer.atlassian.com/cloud/jira/platform/oauth-2-3lo-apps/", "quote": "You'll have to send the link to all the users you want to grant access to. Enabling sharing doesn't make your app available on the Atlassian Marketplace ."}, {"app": "jira", "field": "requirements", "text": "Create an 'OAuth 2.0 integration' in the developer console, configure OAuth 2.0 (3LO) and add Jira API scopes under Permissions.", "src": "https://developer.atlassian.com/cloud/jira/platform/oauth-2-3lo-apps/", "quote": "In the Developer console, select the Create dropdown and choose OAuth 2.0 integration to create an OAuth 2.0 (3LO) app."}, {"app": "jira", "field": "requirements", "text": "Turn on 'Enable sharing' under Distribution before anyone else can authorize the app.", "src": "https://developer.atlassian.com/cloud/jira/platform/oauth-2-3lo-apps/", "quote": "If you want to distribute your app to other users, you must enable sharing. ... Select Distribution in the left menu. Enable sharing using the toggle switch"}, {"app": "jira", "field": "requirements", "text": "Apps that store personal data must report those account IDs to the Personal data reporting API.", "src": "https://developer.atlassian.com/cloud/jira/platform/user-privacy-developer-guide/", "quote": "All apps storing personal data must report user personal data, using the Personal data reporting API ."}, {"app": "jira", "field": "requirements", "text": "Report each stored account once per cycle period (7 days by default, or per the Cycle-Period header), and not more often.", "src": "https://developer.atlassian.com/cloud/jira/platform/user-privacy-developer-guide/", "quote": "By default, the cycle period is 7 days ... you should not send reports more frequently than the cycle period for each accountId ."}, {"app": "jira", "field": "requirements", "text": "Erase or refresh a user's data when the reporting API says so; 3LO apps call POST https://api.atlassian.com/app/report-accounts/.", "src": "https://developer.atlassian.com/cloud/jira/platform/user-privacy-developer-guide/", "quote": "For each user account reported, the Personal data reporting API returns whether each user's personal data must be erased or refreshed."}, {"app": "jira", "field": "requirements", "text": "For Marketplace approval, give reviewers access to a test instance of your software.", "src": "https://developer.atlassian.com/platform/marketplace/knowledge-base/listing-a-third-party-integration-on-the-atlassian-marketplace/", "quote": "In order to test the integration we will need access to a test instance of your software so we can run through the set up and configuration."}, {"app": "jira", "field": "gotchas", "text": "Add offline_access to the scope to get a refresh token at all.", "src": "https://developer.atlassian.com/cloud/jira/platform/oauth-2-3lo-apps/", "quote": "To get a refresh token in your initial authorization flow, add offline_access to the scope parameter of the authorization URL."}, {"app": "jira", "field": "gotchas", "text": "Refresh tokens rotate; store the new one every time, since the old one is disabled.", "src": "https://developer.atlassian.com/cloud/jira/platform/oauth-2-3lo-apps/", "quote": "You receive a new refresh token as well and the refresh token you used for the request is disabled."}, {"app": "jira", "field": "gotchas", "text": "A refresh token expires after 90 days of inactivity, and then the user must re-authorize.", "src": "https://developer.atlassian.com/cloud/jira/platform/oauth-2-3lo-apps/", "quote": "Inactivity expiry time 90 days A rotating refresh token expires if the user is inactive for this period."}, {"app": "jira", "field": "gotchas", "text": "Changing scopes forces users who already consented to consent again.", "src": "https://developer.atlassian.com/cloud/jira/platform/oauth-2-3lo-apps/", "quote": "Note that users who previously consented to the scopes will need to re-consent to the new scopes."}, {"app": "jira", "field": "gotchas", "text": "API calls go to api.atlassian.com/ex/jira/{cloudid}; get the cloudid from accessible-resources.", "src": "https://developer.atlassian.com/cloud/jira/platform/oauth-2-3lo-apps/", "quote": "Jira apps: https://api.atlassian.com/ex/jira/{cloudid}/{api}"}, {"app": "jira", "field": "gotchas", "text": "Site-scoped grants make users pick one site per consent, so multi-site installs mean repeating the flow.", "src": "https://developer.atlassian.com/cloud/jira/platform/oauth-2-3lo-apps/", "quote": "The consent screen currently requires the user to select the site where they want to install the app. ... the user would need to repeat the installation process multiple times."}, {"app": "jira", "field": "gotchas", "text": "Admins can't revoke one user's grant from Connected Apps; they can only uninstall the app.", "src": "https://developer.atlassian.com/cloud/jira/platform/oauth-2-3lo-apps/", "quote": "An admin can't revoke a user's access to an app through the Connected Apps user screen. ... An admin can only choose to uninstall the app"}, {"app": "jira", "field": "gotchas", "text": "Jira 3LO apps can't declare searchable entity properties, so they can't be used in JQL.", "src": "https://developer.atlassian.com/cloud/jira/platform/oauth-2-3lo-apps/", "quote": "Jira apps cannot declare searchable entity properties . This means that if your app uses OAuth 2.0 (3LO), it won't be able to refer to entity properties in JQL queries."}, {"app": "xero", "field": "limits", "text": "Before certification: new apps start on Starter with 5 connections, and Core allows up to 50.", "src": "https://developer.xero.com/documentation/guides/oauth2/limits/", "quote": "New apps default to the starter tier with 5 connections. Moving up to Core will give you up to 50 connections."}, {"app": "xero", "field": "limits", "text": "Each Xero organisation can connect at most five uncertified apps.", "src": "https://developer.xero.com/documentation/guides/oauth2/limits/", "quote": "each organisation or practice is limited to connecting a maximum of five uncertified apps."}, {"app": "xero", "field": "limits", "text": "Starter allows 1,000 API calls per day per organisation; higher tiers allow 5,000.", "src": "https://developer.xero.com/documentation/guides/oauth2/limits/", "quote": "Daily Limit: 1,000 calls per day for starter, 5,000 calls per day for higher tiers"}, {"app": "xero", "field": "limits", "text": "All tiers: 60 calls per minute and 5 concurrent calls per organisation.", "src": "https://developer.xero.com/documentation/guides/oauth2/limits/", "quote": "Concurrent Limit: 5 calls in progress at one time Minute Limit: 60 calls per minute"}, {"app": "xero", "field": "requirements", "text": "Plus, Advanced and Enterprise tiers require app certification.", "src": "https://developer.xero.com/pricing", "quote": "Prerequisites App Certification App Certification App Certification"}, {"app": "xero", "field": "requirements", "text": "Core and above require a payment method on file.", "src": "https://developer.xero.com/pricing", "quote": "Payment Method Not Applicable Required Required Required Required"}, {"app": "xero", "field": "requirements", "text": "Certification requires the offline_access scope.", "src": "https://developer.xero.com/documentation/xero-app-store/app-partner-guides/certification-checkpoints/", "quote": "Using the offline_access scope is a requirement for certification."}, {"app": "xero", "field": "requirements", "text": "Certification needs a connect/disconnect settings page showing the connected tenant name and status.", "src": "https://developer.xero.com/documentation/xero-app-store/app-partner-guides/certification-checkpoints/", "quote": "Ensure you implement a setup page that allows users to connect to Xero ... Display the name of the tenant that has been connected. Display the current status of the connection(s)"}, {"app": "xero", "field": "requirements", "text": "The app name cannot include the word Xero.", "src": "https://developer.xero.com/documentation/xero-app-store/app-partner-guides/certification-checkpoints/", "quote": "The application name must reflect the go-to-market name of your app or product and cannot include the word Xero."}, {"app": "xero", "field": "requirements", "text": "Listing on the Xero App Store requires the Plus tier or higher.", "src": "https://developer.xero.com/documentation/xero-app-store/app-partner-guides/certification-checkpoints/", "quote": "To be listed on the Xero App Store, you will need to be in the Plus tier or higher."}, {"app": "xero", "field": "gotchas", "text": "Composio has no managed Xero app, so you must bring your own credentials.", "src": "https://docs.composio.dev/toolkits/xero", "quote": "Composio-managed OAuth not available"}, {"app": "xero", "field": "gotchas", "text": "Data from Xero's APIs may not be used to train AI/ML models.", "src": "https://developer.xero.com/pricing", "quote": "data obtained from Xero's APIs may not be used to train AI/ML models."}, {"app": "xero", "field": "gotchas", "text": "Access tokens last 30 minutes; refresh tokens last 60 days and rotate on each use.", "src": "https://developer.xero.com/documentation/xero-app-store/app-partner-guides/certification-checkpoints/", "quote": "Instead of the access token lasting for 30 minutes, offline_access scope will allow the refresh token to request a new access token for 60 days."}, {"app": "xero", "field": "gotchas", "text": "Apps created on or after 2 March 2026 use Xero's new granular scopes.", "src": "https://developer.xero.com/documentation/xero-app-store/app-partner-guides/certification-checkpoints/", "quote": "Apps created on or after 2 March 2026 will use the new granular scopes"}, {"app": "xero", "field": "gotchas", "text": "Redirect URI must use https with no trailing slash.", "src": "https://composio.dev/auth/xero", "quote": "No trailing slash. The protocol must be https ."}, {"app": "xero", "field": "review", "text": "Xero app certification (required for the Plus tier and above, over 50 connections) | wait: not stated", "src": "https://developer.xero.com/pricing", "quote": "Connections (maximum) 5 50 1000 10,000 No Limit Prerequisites    App Certification App Certification App Certification"}, {"app": "xero", "field": "cost", "text": "Starter free (5 connections); Core $35 AUD/mo (50); Plus $245 AUD/mo (1,000), tax exclusive", "src": "https://developer.xero.com/pricing", "quote": "Monthly Tier Fee No charge $35 AUD $245 AUD $1445 AUD Price on Application ... Pricing is tax exclusive"}, {"app": "asana", "field": "limits", "text": "Before submission, Asana says the app is for your own organization, development, or internal tools.", "src": "https://developers.asana.com/docs/submit-your-app", "quote": "Make your app available to users in any Asana workspace, beyond your own organization or development environment ... If you're building an internal tool or testing your integration"}, {"app": "asana", "field": "limits", "text": "Rate limit is per token: 150 requests/min on free domains, 1,500/min on paid domains.", "src": "https://developers.asana.com/docs/rate-limits", "quote": "Limits are allocated per authorization token . ... Domain type Maximum requests per minute Free 150 Paid 1,500"}, {"app": "asana", "field": "limits", "text": "Search API is limited to 60 requests per minute.", "src": "https://developers.asana.com/docs/rate-limits", "quote": "Calls to the search API are limited to 60 requests per minute ."}, {"app": "asana", "field": "requirements", "text": "Non-native apps must use an https redirect URL.", "src": "https://developers.asana.com/docs/oauth", "quote": "For security reasons, non-native applications must supply a \"https\" URL"}, {"app": "asana", "field": "requirements", "text": "Submission requires a privacy policy URL and a support page URL.", "src": "https://developers.asana.com/docs/submit-your-app", "quote": "Adding a support page URL so that users can seek help. Adding your app's privacy policy URL."}, {"app": "asana", "field": "requirements", "text": "Submission requires an app icon, images, a short description and a 250+ character long description.", "src": "https://developers.asana.com/docs/submit-your-app", "quote": "Adding an app icon ... Adding app images ... Adding a short description ... Adding a longer description (at least 250 characters)"}, {"app": "asana", "field": "requirements", "text": "Apps submitted to the App Directory must be shared to Any workspace.", "src": "https://developers.asana.com/docs/manage-distribution", "quote": "All apps submitted for publication to the app directory must be shared to Any workspace ."}, {"app": "asana", "field": "gotchas", "text": "Turning on Full permissions means you cannot request specific scopes.", "src": "https://developers.asana.com/docs/oauth", "quote": "When Full permissions is enabled, you cannot request specific scopes."}, {"app": "asana", "field": "gotchas", "text": "Scope requests are not additive; always send the full set you need.", "src": "https://developers.asana.com/docs/oauth", "quote": "Subsequent requests will not be additive. You must specify the full set of scopes needed."}, {"app": "asana", "field": "gotchas", "text": "The app must be available in the user's workspace before they can authorize.", "src": "https://developers.asana.com/docs/oauth", "quote": "In order for a user to be able to authorize the OAuth application via this user authorization endpoint, the application must be available in the user's workspace."}, {"app": "asana", "field": "gotchas", "text": "Enterprise admins can control which apps are allowed from the admin console.", "src": "https://developers.asana.com/docs/manage-distribution", "quote": "In many Enterprise organizations, admins manage which apps can be used from the admin console."}, {"app": "asana", "field": "gotchas", "text": "Switching from Any workspace to Specific workspace blocks new authorizations from other workspaces.", "src": "https://developers.asana.com/docs/manage-distribution", "quote": "changing the sharing settings from Any workspace to Specific workspace will block any new authorizations from users outside the specified workspace"}, {"app": "asana", "field": "review", "text": "Asana app submission review (needed to serve any workspace or list in the App Directory) | wait: Initial response within one week", "src": "https://developers.asana.com/docs/submit-your-app", "quote": "We aim to provide an initial response on app submissions within one week ."}, {"app": "slack", "field": "limits", "text": "Before Marketplace approval: conversations.history and conversations.replies are limited to 1 request per minute for new unlisted commercial apps.", "src": "https://docs.slack.dev/changelog/2025/05/29/rate-limit-changes-for-non-marketplace-apps", "quote": "limited to 1 request per minute, unless they are approved for the Slack Marketplace."}, {"app": "slack", "field": "limits", "text": "Before Marketplace approval: those two methods return at most 15 objects per request.", "src": "https://docs.slack.dev/changelog/2025/05/29/rate-limit-changes-for-non-marketplace-apps", "quote": "The maximum and default for the limit parameter has been reduced to 15 objects."}, {"app": "slack", "field": "limits", "text": "Internal customer-built apps keep 50+ requests per minute and up to 1,000 objects per request.", "src": "https://docs.slack.dev/changelog/2025/05/29/rate-limit-changes-for-non-marketplace-apps", "quote": "For Custom apps, the conversations.history and conversations.replies API methods are limited to 50+ requests per minute. The maximum and default values for the limit parameter are 1,000 objects."}, {"app": "slack", "field": "requirements", "text": "Redirect URLs must use HTTPS.", "src": "https://docs.slack.dev/authentication/installing-with-oauth", "quote": "The redirect_uri must use HTTPS. ... A Redirect URL must also use HTTPS."}, {"app": "slack", "field": "requirements", "text": "Marketplace submission requires the app to be installed on 10 or more active workspaces.", "src": "https://docs.slack.dev/slack-marketplace/slack-marketplace-review-guide", "quote": "Your app has been installed on 10 or more active workspaces ... An active workspace is a workspace that has been used in the past 28 days."}, {"app": "slack", "field": "requirements", "text": "Installing on other workspaces requires Activate Public Distribution under Manage Distribution.", "src": "https://docs.slack.dev/app-management/distribution", "quote": "Scroll to Share Your App with Other Workspaces within the Manage Distribution section. ... Click Activate Public Distribution ."}, {"app": "slack", "field": "requirements", "text": "A short video demo of install, OAuth, setup and uninstall is optional but speeds up Marketplace review.", "src": "https://docs.slack.dev/slack-marketplace/slack-marketplace-review-guide", "quote": "You can help us review your app more quickly by providing us with a short video demo. ... full installation and OAuth flow, set-up process, and end-to-end functionality, including uninstallation."}, {"app": "slack", "field": "gotchas", "text": "Slack's updated API terms say the Marketplace is the only appropriate channel for commercially distributing apps.", "src": "https://docs.slack.dev/changelog/2025/05/29/rate-limit-changes-for-non-marketplace-apps", "quote": "The updated terms confirm that the Slack Marketplace is the only appropriate channel for commercially distributing apps built with Slack APIs"}, {"app": "slack", "field": "gotchas", "text": "Workspaces that require Marketplace or approved apps show a warning or need admin approval for unlisted apps.", "src": "https://docs.composio.dev/toolkits/slack", "quote": "workspaces with stricter app policies may require admin approval before the connection can complete."}, {"app": "slack", "field": "gotchas", "text": "Each preliminary resubmission resets your place in the review queue.", "src": "https://docs.slack.dev/slack-marketplace/slack-marketplace-review-guide", "quote": "During this part of the review, your place in the queue is reset each time you resubmit."}, {"app": "slack", "field": "gotchas", "text": "With your own app, Slack triggers need the Composio custom OAuth webhook setup.", "src": "https://docs.composio.dev/toolkits/slack", "quote": "If you bring your own Slack OAuth app, see Custom OAuth webhooks ."}, {"app": "slack", "field": "gotchas", "text": "Every scope in the Composio auth config must also be added in the Slack app, or calls fail with insufficient scopes.", "src": "https://docs.composio.dev/toolkits/slack", "quote": "\"Insufficient scopes\" (ensure all scopes from your auth config are configured in the Slack app)."}, {"app": "discord", "field": "limits", "text": "All bots can make up to 50 requests per second to the API (global limit).", "src": "https://docs.discord.com/developers/topics/rate-limits", "quote": "All bots can make up to 50 requests per second to our API."}, {"app": "discord", "field": "limits", "text": "Bots with privileged intents need review once more than 10,000 unique users can see the app.", "src": "https://docs.discord.com/developers/gateway/getting-started-with-privileged-intent-review", "quote": "That threshold is now based on the number of unique users who can see your app ... If that number exceeds 10,000, your app needs to apply for Privileged Intent access."}, {"app": "discord", "field": "requirements", "text": "Verification is required for apps in 100+ guilds.", "src": "https://docs.discord.com/developers/events/gateway", "quote": "For verified apps (required for apps in 100+ guilds), the intent must also be approved after the verification process to use the intent."}, {"app": "discord", "field": "requirements", "text": "App Verification requires the team owner to complete identity and application verification.", "src": "https://docs.discord.com/developers/discovery/enabling-discovery", "quote": "To enable Discovery for your app, we require your team owner to complete identity and application verification."}, {"app": "discord", "field": "requirements", "text": "The redirect_uri must be one you registered on the application.", "src": "https://docs.discord.com/developers/topics/oauth2", "quote": "redirect_uri is whatever URL you registered when creating your application, url-encoded."}, {"app": "discord", "field": "gotchas", "text": "Access tokens expire (example expires_in is 604800 seconds), so use the refresh token.", "src": "https://docs.discord.com/developers/topics/oauth2", "quote": "expires_in is how long, in seconds, until the returned access token expires, allowing you to anticipate the expiration and refresh the token."}, {"app": "discord", "field": "gotchas", "text": "Some scopes such as voice, rpc and dm_channels.read are only available to approved partners.", "src": "https://docs.discord.com/developers/topics/oauth2", "quote": "dm_channels.read ... only available to approved partners"}, {"app": "discord", "field": "gotchas", "text": "Several Composio Discord tools are deprecated because they need a bot token, not a user OAuth connection.", "src": "https://docs.composio.dev/toolkits/discord", "quote": "DEPRECATED: This Discord endpoint requires a bot token and cannot be used by an OAuth2 user connection."}, {"app": "discord", "field": "gotchas", "text": "Approved privileged intent access must be reapplied for every year.", "src": "https://docs.discord.com/developers/gateway/getting-started-with-privileged-intent-review", "quote": "Apps that already have Privileged Intent access granted from a prior review must reapply each year through the Developer Portal for their continued access."}, {"app": "googlecalendar", "field": "limits", "text": "Before approval: Testing mode is limited to 100 test users listed on the consent screen.", "src": "https://support.google.com/cloud/answer/15549945", "quote": "Projects configured with a publishing status of Testing are limited to up to 100 test users listed in the OAuth consent screen."}, {"app": "googlecalendar", "field": "limits", "text": "Before approval: test-user authorizations and refresh tokens expire 7 days after consent.", "src": "https://support.google.com/cloud/answer/15549945", "quote": "Authorizations by a test user will expire seven days from the time of consent. If your OAuth client requests an offline access type and receives a refresh token, that token will also expire."}, {"app": "googlecalendar", "field": "limits", "text": "Before approval: an In-production app requesting unapproved sensitive or restricted scopes shows the unverified app screen.", "src": "https://support.google.com/cloud/answer/15549945", "quote": "Google will display an Unverified apps warning message if your project's OAuth clients request authorization of scopes considered sensitive or restricted before your project has completed verification"}, {"app": "googlecalendar", "field": "requirements", "text": "Verify ownership of your authorized domains in Google Search Console.", "src": "https://developers.google.com/identity/protocols/oauth2/production-readiness/sensitive-scope-verification", "quote": "Verify ownership of your project's authorized domains within the Google Search Console ."}, {"app": "googlecalendar", "field": "requirements", "text": "Host a public home page and a privacy policy on the same domain, both linked from the consent screen.", "src": "https://developers.google.com/identity/protocols/oauth2/production-readiness/sensitive-scope-verification", "quote": "The privacy policy must be visible to users, hosted within the same domain as your application's home page, and linked to on the OAuth consent screen of the Google API Console."}, {"app": "googlecalendar", "field": "requirements", "text": "The privacy policy must disclose how the app accesses, uses, stores, or shares Google user data.", "src": "https://developers.google.com/identity/protocols/oauth2/production-readiness/sensitive-scope-verification", "quote": "The privacy policy must disclose the manner in which your application accesses, uses, stores, or shares Google user data."}, {"app": "googlecalendar", "field": "requirements", "text": "Give a written justification for each sensitive scope, including why a narrower scope is not enough.", "src": "https://developers.google.com/identity/protocols/oauth2/production-readiness/sensitive-scope-verification", "quote": "Prepare a detailed justification for each requested sensitive scope, as well as an explanation for why a narrower scope isn't sufficient."}, {"app": "googlecalendar", "field": "requirements", "text": "Submit an unlisted YouTube video showing the consent flow, the client ID in the address bar, and each scope in use.", "src": "https://developers.google.com/identity/protocols/oauth2/production-readiness/sensitive-scope-verification", "quote": "Show that the browser address bar of the OAuth consent screen correctly includes your app's OAuth client ID."}, {"app": "googlecalendar", "field": "requirements", "text": "You must publish your branding before you can request verification for data access.", "src": "https://developers.google.com/identity/protocols/oauth2/production-readiness/sensitive-scope-verification", "quote": "Note that you must have a published branding status before you can request verification for data access."}, {"app": "googlecalendar", "field": "requirements", "text": "Internal-only apps (Workspace-owned project, Internal audience) skip verification and the 100-user cap but only work in that org.", "src": "https://support.google.com/cloud/answer/13464323", "quote": "Your app will not be subject to the unverified app screen or the 100-user cap if it's designated as internal-only."}, {"app": "googlecalendar", "field": "gotchas", "text": "Google lists reading Google Calendar events as an example of a sensitive scope.", "src": "https://developers.google.com/identity/protocols/oauth2/production-readiness/sensitive-scope-verification", "quote": "Examples of sensitive scopes include reading events stored in Google Calendar, storing a new contact in Google Contacts, or deleting a YouTube video."}, {"app": "googlecalendar", "field": "gotchas", "text": "No Calendar API scope is on Google's restricted scope list.", "src": "https://support.google.com/cloud/answer/13464325", "quote": "The following scopes are categorized as \"restricted\" Gmail API"}, {"app": "googlecalendar", "field": "gotchas", "text": "Narrower scopes such as calendar.events.owned and calendar.freebusy exist if you don't need full calendar access.", "src": "https://developers.google.com/workspace/calendar/api/auth", "quote": "https://www.googleapis.com/auth/calendar.events.owned See, create, change, and delete events on Google calendars you own."}, {"app": "googlecalendar", "field": "gotchas", "text": "Google requires you to request the narrowest scope that provides the feature.", "src": "https://developers.google.com/identity/protocols/oauth2/production-readiness/sensitive-scope-verification", "quote": "You must request the narrowest scope necessary for your app's functionality"}, {"app": "googlecalendar", "field": "gotchas", "text": "Google's FAQ estimates sensitive scope verification at 10 business days, which is longer than the 3-5 days on the developer page.", "src": "https://support.google.com/cloud/answer/13463817", "quote": "10 Business days"}, {"app": "googlecalendar", "field": "gotchas", "text": "Limits apply to refresh tokens: 100 per Google Account per client ID, and creating a new one silently invalidates the oldest.", "src": "https://developers.google.com/identity/protocols/oauth2", "quote": "If the limit is reached, creating a new refresh token automatically invalidates the oldest refresh token without warning."}, {"app": "googlecalendar", "field": "gotchas", "text": "Refresh tokens stop working after 6 months unused or if the user revokes access.", "src": "https://developers.google.com/identity/protocols/oauth2", "quote": "The user has revoked your app's access . The refresh token has not been used for six months."}, {"app": "googlecalendar", "field": "gotchas", "text": "Your OAuth redirect URI must exactly match oauth_redirect_uri in the Composio auth config; some defaults still use /api/v1/auth-apps/add.", "src": "https://docs.composio.dev/docs/auth-configuration/custom-auth-configs", "quote": "The redirect URI in your OAuth app must exactly match oauth_redirect_uri in your Composio auth config. Some toolkit defaults still use https://backend.composio.dev/api/v1/auth-apps/add"}, {"app": "googlecalendar", "field": "gotchas", "text": "Use separate Google Cloud projects for testing and production, and submit only the production project for verification.", "src": "https://support.google.com/cloud/answer/13464323", "quote": "You should only submit “production” tier projects for verification."}, {"app": "googlecalendar", "field": "gotchas", "text": "Workspace admins can restrict sensitive scopes to OAuth clients they explicitly mark as trusted.", "src": "https://developers.google.com/identity/protocols/oauth2/production-readiness/sensitive-scope-verification", "quote": "Google Workspace organization administrators might restrict access to sensitive scopes to prevent access by OAuth client IDs that the organization doesn't explicitly mark as trusted."}, {"app": "shopify", "field": "limits", "text": "Before approval: a custom-distribution app installs only on one store, stores in one Plus organization, or development stores.", "src": "https://shopify.dev/docs/apps/launch/distribution", "quote": "Custom distribution Installed on a single Shopify store, on multiple stores that belong to the same Plus organization, or on development stores"}, {"app": "shopify", "field": "requirements", "text": "App Store apps must subscribe to the customers/data_request, customers/redact and shop/redact compliance webhooks.", "src": "https://shopify.dev/docs/apps/build/compliance/privacy-law-compliance", "quote": "Every app that's distributed through the Shopify App Store must subscribe to the following compliance webhook topics:"}, {"app": "shopify", "field": "requirements", "text": "New public apps must be built only with the GraphQL Admin API.", "src": "https://shopify.dev/docs/apps/launch/shopify-app-store/app-store-requirements", "quote": "As of April 1, 2025 all new public apps must be built exclusively with the GraphQL Admin API ."}, {"app": "shopify", "field": "requirements", "text": "Review submissions need a screencast, working test credentials and an emergency developer contact.", "src": "https://shopify.dev/docs/apps/launch/shopify-app-store/app-store-requirements", "quote": "4.5.6 Provide an emergency developer contact. Add an emergency developer contact to your Partner Dashboard."}, {"app": "shopify", "field": "requirements", "text": "The app must authenticate with OAuth immediately after install, before any other step.", "src": "https://shopify.dev/docs/apps/launch/shopify-app-store/app-store-requirements", "quote": "2.3.2 Authenticate immediately after install. Your app must immediately authenticate using OAuth before any other steps occur."}, {"app": "shopify", "field": "requirements", "text": "App charges must go through Shopify App Pricing or the Billing API.", "src": "https://shopify.dev/docs/apps/launch/shopify-app-store/app-store-requirements", "quote": "Your app must use Shopify App Pricing or the Shopify Billing API for any app charges."}, {"app": "shopify", "field": "gotchas", "text": "Composio has no managed Shopify app, so you must bring your own credentials.", "src": "https://docs.composio.dev/toolkits/shopify", "quote": "Authentication Details Composio-managed OAuth not available OAuth2 S2S_OAUTH2"}, {"app": "shopify", "field": "gotchas", "text": "New public apps must use expiring offline tokens that last 1 hour, with refresh tokens valid 90 days.", "src": "https://shopify.dev/docs/apps/build/authentication-authorization/access-token-types/offline-access-tokens", "quote": "Expiring offline access token 1 hour ( expires_in is 3600 ) Refresh token for an expiring offline access token 90 days ( refresh_token_expires_in is 7776000 ) when issued."}, {"app": "shopify", "field": "gotchas", "text": "You cannot change the distribution method after you select it.", "src": "https://shopify.dev/docs/apps/launch/distribution", "quote": "You can't change the distribution method after you select it."}, {"app": "shopify", "field": "gotchas", "text": "Composio asks for the store subdomain (e.g. je0xpi-12) when connecting an account.", "src": "https://composio.dev/auth/shopify", "quote": "Store subdomain: Enter your Shopify store's subdomain. If your store URL is https://je0xpi-12.myshopify.com , enter je0xpi-12"}, {"app": "shopify", "field": "gotchas", "text": "Order updates can 403 without the read_all_orders scope.", "src": "https://docs.composio.dev/toolkits/shopify", "quote": "Shopify order update 403s can be caused by missing read_all_orders scope"}, {"app": "shopify", "field": "cost", "text": "One-time $19 USD App Store registration fee per Partner account", "src": "https://shopify.dev/docs/apps/launch/distribution/revenue-share", "quote": "you need to register with the Shopify App Store for a one-time fee of $19 USD per Partner account."}, {"app": "linkedin", "field": "limits", "text": "Without approval, only open permissions work: profile, email (OpenID Connect) and w_member_social.", "src": "https://learn.microsoft.com/en-us/linkedin/shared/authentication/getting-access", "quote": "Open Permissions are the only permissions that are available to all developers without special approval."}, {"app": "linkedin", "field": "limits", "text": "Community Management Development tier allows 500 requests per app and 100 per member.", "src": "https://learn.microsoft.com/en-us/linkedin/marketing/community-management/community-management-overview", "quote": "Per App : Increased from 100 to 500 requests. Per Member : Increased from 10 to 100 requests."}, {"app": "linkedin", "field": "limits", "text": "Rate limits are daily, reset at midnight UTC, and are not published; check the app's Analytics tab.", "src": "https://learn.microsoft.com/en-us/linkedin/shared/api-guide/concepts/rate-limits", "quote": "Standard rate limits are not published in documentation."}, {"app": "linkedin", "field": "requirements", "text": "Redirect URLs must be absolute HTTPS URLs with no # fragment.", "src": "https://learn.microsoft.com/en-us/linkedin/shared/authentication/authorization-code-flow", "quote": "URLs cannot include a # https://dev.example.com/auth/linkedin/callback#linkedin is invalid."}, {"app": "linkedin", "field": "requirements", "text": "Creating the app asks for an app name, a Company page URL and a logo.", "src": "https://composio.dev/auth/linkedin", "quote": "enter the basic required app details, like the App name, Company page URL, and the logo that users will see when they authorize with your app."}, {"app": "linkedin", "field": "requirements", "text": "Self-serve products are added from the Products tab of the app.", "src": "https://learn.microsoft.com/en-us/linkedin/consumer/integrations/self-serve/share-on-linkedin", "quote": "Select your app from My Apps , navigate to the Products tab, and add the Share on LinkedIn product which will grant you w_member_social ."}, {"app": "linkedin", "field": "requirements", "text": "Standard tier requests need a screencast showing each use case.", "src": "https://learn.microsoft.com/en-us/linkedin/marketing/community-management/community-management-overview", "quote": "When applying for Standard Tier, provide a screencast video demonstrating each use case specified in your access request form"}, {"app": "linkedin", "field": "gotchas", "text": "Access tokens last 60 days; programmatic refresh tokens are for approved Marketing Developer Platform partners.", "src": "https://learn.microsoft.com/en-us/linkedin/shared/authentication/programmatic-refresh-tokens", "quote": "By default, access tokens are valid for 60 days and programmatic refresh tokens are valid for a year."}, {"app": "linkedin", "field": "gotchas", "text": "Changing an app's scopes means users must re-authenticate.", "src": "https://learn.microsoft.com/en-us/linkedin/shared/authentication/authorization-code-flow", "quote": "If the scope permissions are changed in your app, your users must re-authenticate"}, {"app": "linkedin", "field": "gotchas", "text": "w_member_social and r_organization_admin cannot be used together.", "src": "https://docs.composio.dev/toolkits/linkedin", "quote": "LinkedIn restricts certain scope combinations. For example, w_member_social and r_organization_admin cannot be used together."}, {"app": "linkedin", "field": "gotchas", "text": "Community Management access must be requested on a new app with no other API products.", "src": "https://learn.microsoft.com/en-us/linkedin/marketing/community-management/community-management-overview", "quote": "Only request Community Management API Development Tier access with new developer applications that don't have access to other API products."}, {"app": "linkedin", "field": "gotchas", "text": "r_member_social is closed and LinkedIn is not accepting requests for it.", "src": "https://learn.microsoft.com/en-us/linkedin/marketing/community-management/community-management-overview", "quote": "r_member_social is a closed permission. We're not accepting access requests at this time due to resource constraints."}, {"app": "linear", "field": "limits", "text": "OAuth apps get 5,000 requests and 2,000,000 complexity points per hour per user or app user.", "src": "https://linear.app/developers/rate-limiting", "quote": "OAuth App 5,000 User (or App User) 1 hour"}, {"app": "linear", "field": "requirements", "text": "Configure your redirect callback URLs on the app; the token exchange must use the same redirect_uri.", "src": "https://linear.app/developers/oauth-2-0-authentication", "quote": "redirect_uri (required) Same redirect URI which you used in the previous step"}, {"app": "linear", "field": "requirements", "text": "Linear highly recommends creating a dedicated workspace to own the OAuth app.", "src": "https://linear.app/developers/oauth-2-0-authentication", "quote": "It is highly recommended you create a workspace for the purpose of managing the OAuth2 Application, as each admin user will have access."}, {"app": "linear", "field": "requirements", "text": "Directory listings are for useful integrations built by formal companies, not hobby or low-effort apps.", "src": "https://linear.app/docs/integration-directory", "quote": "We'll accept integrations that we think are useful to the community and are built by formal companies. We generally do not accept scripts, low-effort/vibe coded or apps built by hobbyists"}, {"app": "linear", "field": "requirements", "text": "A directory listing needs a submission form, 320x320 color and white icons, and 1-3 showcase images at 1600x1000.", "src": "https://linear.app/docs/integration-directory", "quote": "Showcase images (1-3 max) 1600px x 1000px in .svg, .jpeg, or .png file format"}, {"app": "linear", "field": "gotchas", "text": "Authorization-code access tokens are valid for 24 hours and come with a refresh token.", "src": "https://linear.app/developers/oauth-2-0-authentication", "quote": "a valid access token and refresh token will be returned in the response. The access token is valid for 24 hours"}, {"app": "linear", "field": "gotchas", "text": "All OAuth apps were moved to the refresh token system on April 1, 2026.", "src": "https://linear.app/developers/oauth-2-0-authentication", "quote": "All OAuth2 applications were migrated to the new refresh token system on April 1, 2026."}, {"app": "linear", "field": "gotchas", "text": "Each refresh returns a new access and refresh token; a lost response can be replayed within 30 minutes.", "src": "https://linear.app/developers/oauth-2-0-authentication", "quote": "you can replay the original request to retrieve the new refresh token up to 30 minutes after the original request."}, {"app": "linear", "field": "gotchas", "text": "actor=app creates resources as the app instead of the authorizing user.", "src": "https://linear.app/developers/oauth-2-0-authentication", "quote": "app - Resources are created as the application."}, {"app": "linear", "field": "gotchas", "text": "Request the admin scope only when absolutely necessary.", "src": "https://linear.app/developers/oauth-2-0-authentication", "quote": "admin - Full access to admin level endpoints. You should never ask for this permission unless it's absolutely needed"}, {"app": "linear", "field": "gotchas", "text": "Every admin of the workspace that owns the app can access the app's settings.", "src": "https://linear.app/developers/oauth-2-0-authentication", "quote": "It is highly recommended you create a workspace for the purpose of managing the OAuth2 Application, as each admin user will have access."}, {"app": "mailchimp", "field": "limits", "text": "Limit of 10 simultaneous connections per user; there is no way to raise it.", "src": "https://mailchimp.com/developer/marketing/api-concepts/rate-limits-and-timeouts", "quote": "Currently there are no options to raise the limit on a per-customer basis. Throttling The Marketing API has a limit of 10 simultaneous connections."}, {"app": "mailchimp", "field": "limits", "text": "API calls time out after 120 seconds.", "src": "https://mailchimp.com/developer/marketing/api-concepts/rate-limits-and-timeouts", "quote": "The Marketing API has a 120-second timeout on API calls."}, {"app": "mailchimp", "field": "limits", "text": "Some Composio Mailchimp tools need at least the Essentials plan.", "src": "https://docs.composio.dev/toolkits/mailchimp", "quote": "Some Mailchimp API/tool capabilities require at least the Mailchimp Essentials plan."}, {"app": "mailchimp", "field": "requirements", "text": "Register the app on the Registered Apps page in your Mailchimp account.", "src": "https://mailchimp.com/developer/marketing/build/start-developing/set-up-an-oauth-app", "quote": "Navigate to the Registered Apps page in your Mailchimp account Click Register An App"}, {"app": "mailchimp", "field": "requirements", "text": "HTTPS for the redirect URI is strongly recommended but not enforced.", "src": "https://mailchimp.com/developer/marketing/api-concepts/authentication/oauth-2", "quote": "For security, we strongly recommend—but do not enforce—using HTTPS for your redirect_uri ."}, {"app": "mailchimp", "field": "requirements", "text": "Delete stored tokens when a user disconnects or uninstalls your app.", "src": "https://mailchimp.com/developer/marketing/api-concepts/authentication/oauth-2", "quote": "when a user disconnects or uninstalls your application, delete the access token you stored for them"}, {"app": "mailchimp", "field": "gotchas", "text": "The client secret is shown only once at registration.", "src": "https://mailchimp.com/developer/marketing/build/start-developing/set-up-an-oauth-app", "quote": "This is the only time you'll be able to see client_secret , so you'll need to copy it and store it securely."}, {"app": "mailchimp", "field": "gotchas", "text": "Access tokens never expire and there is no refresh token.", "src": "https://mailchimp.com/developer/marketing/api-concepts/authentication/oauth-2", "quote": "Mailchimp access tokens have no expiry, so there is no refresh_token and nothing to rotate on a schedule."}, {"app": "mailchimp", "field": "gotchas", "text": "A token is revoked if the authorizing user is removed from the account.", "src": "https://mailchimp.com/developer/marketing/api-concepts/authentication", "quote": "If that user is removed from the account, the token is revoked."}, {"app": "mailchimp", "field": "gotchas", "text": "API access is bounded by the authorizing user's role; use an admin where possible.", "src": "https://mailchimp.com/developer/marketing/api-concepts/authentication", "quote": "When creating a key or authorizing an app, use an admin user where you can."}]};
